/* Déclic — Notions fondamentales : analyse (2) — calcul de limites, fonctions réelles, variations, continuité */
(()=>{
/* ---------- helpers locaux ---------- */
const B=(c,h)=>`<div class="blk ${c}">${h}</div>`;            // bloc def / thm / prop / idea / why / ex / warn / keep
const RP=h=>`<div class="blk" data-t="Rappel">${h}</div>`;     // rappel d’une notion vue avant
const tab=(head,rows)=>`<table style="border-collapse:collapse;margin:6px auto"><tr>${head.map(h=>`<th style="border-bottom:2px solid var(--line);padding:4px 9px">${h}</th>`).join('')}</tr>${rows.map(r=>`<tr>${r.map(c=>`<td style="padding:4px 9px;text-align:center;border-bottom:1px solid var(--line)">${c}</td>`).join('')}</tr>`).join('')}</table>`;
const fx=(v,d)=>v.toFixed(d).replace('.',',').replace('-','−');
const fl=Math.floor;
// nuage de points d’une suite u(n) pour n0 ≤ n ≤ n1, avec une limite L en pointillé
function seq(u,n1,o={}){ const yr=o.y||[-1.5,3.5], P=plane({x:[-0.5,n1+1],y:yr,h:o.h||200,grid:false,lx:o.lx||5,ly:o.ly||1});
  if(o.L!==undefined) P.seg(0,o.L,n1+1,o.L,{c:'var(--ok)',w:1.5,dash:true});
  if(o.band!==undefined) P.rect(0,o.L-o.band,n1+1,2*o.band,{fill:'var(--ok)',fo:.15,c:null});
  for(let n=o.n0??1;n<=n1;n++){ const y=u(n); if(isFinite(y)&&y>=yr[0]&&y<=yr[1]) P.dot(n,y,{r:o.r||3.5,c:o.c||'var(--accent)'}); }
  if(o.ex) o.ex(P); return P; }
// graphe d’une fonction sur un repère standard
function graph(f,o={}){ const P=plane({x:o.x||[-4,4],y:o.y||[-4,4],h:o.h,lab:o.lab??1,grid:o.grid}); if(f) P.fn(f,{from:o.from,to:o.to,c:o.c,n:o.n}); if(o.ex) o.ex(P); return P; }
// escalier de la partie entière
function stairs(P,a,b,q={}){ for(let k=Math.floor(a);k<b;k++){ P.seg(k,k,k+1,k,Object.assign({w:3.5},q)); P.dot(k,k,{r:4,c:q.c||'var(--accent)'}); P.circ(k+1,k,.1,{c:q.c||'var(--accent)',w:2,fill:'var(--surface)',fo:1}); } return P; }

COURS.push(
/* ===================== 1. CALCULER DES LIMITES DE SUITES ===================== */
{subj:'gred',sem:'ana',id:'gred-calcul-limites',h:'Calculer des limites de suites',p:'Les règles de calcul, les limites de référence, les gendarmes, les formes indéterminées et leurs remèdes, les suites adjacentes, puis les développements décimaux vus comme des limites.',steps:[
  {kind:'Théorie',h:'Les opérations sur les limites',
   p:`<p>Tu sais ce que veut dire <i>uₙ</i> → <i>a</i>. Mais revenir à la définition pour chaque suite serait épuisant. L’idée : calculer une fois pour toutes les limites de quelques briques simples, puis les assembler avec des règles sûres.</p>
${RP('<p><i>uₙ</i> → <i>a</i> signifie : pour tout ε &gt; 0, il existe un rang <i>N</i> tel que |<i>uₙ</i> − <i>a</i>| &lt; ε dès que <i>n</i> ≥ <i>N</i>. Une suite convergente est bornée et sa limite est unique.</p>')}
${B('thm','<p>Si <i>uₙ</i> → <i>a</i> et <i>vₙ</i> → <i>b</i> (limites finies), alors :</p><ul><li><i>uₙ</i> + <i>vₙ</i> → <i>a</i> + <i>b</i>, et λ<i>uₙ</i> → λ<i>a</i> pour tout réel λ ;</li><li><i>uₙ</i> · <i>vₙ</i> → <i>a</i> · <i>b</i> ;</li><li>si <i>b</i> ≠ 0, alors <i>vₙ</i> ≠ 0 à partir d’un certain rang et <i>uₙ</i>/<i>vₙ</i> → <i>a</i>/<i>b</i>.</li></ul>')}
${B('why','<p>Pour la somme. Soit ε &gt; 0. L’inégalité triangulaire donne |(<i>uₙ</i> + <i>vₙ</i>) − (<i>a</i> + <i>b</i>)| ≤ |<i>uₙ</i> − <i>a</i>| + |<i>vₙ</i> − <i>b</i>|. On demande à chaque suite d’être à moins de <b>ε/2</b> de sa limite : c’est vrai à partir d’un rang <i>N</i>₁ pour la première, <i>N</i>₂ pour la seconde. Dès que <i>n</i> ≥ max(<i>N</i>₁, <i>N</i>₂), l’écart total est inférieur à ε/2 + ε/2 = ε. Pour le produit, on écrit <i>uₙvₙ</i> − <i>ab</i> = <i>uₙ</i>(<i>vₙ</i> − <i>b</i>) + <i>b</i>(<i>uₙ</i> − <i>a</i>) et on utilise que (<i>uₙ</i>) est bornée.</p>')}
${B('ex','<p>Comme 1/<i>n</i> → 0 et 1/<i>n</i>² → 0 : (2 + 1/<i>n</i>)(3 − 1/<i>n</i>²) → 2 · 3 = 6, et (1 + 1/<i>n</i>)/(4 − 2/<i>n</i>) → 1/4.</p>')}
${B('warn','<p>Ces règles supposent des limites <b>finies</b>. Avec des suites qui tendent vers l’infini, certaines combinaisons ne se décident pas d’avance : ce sont les formes indéterminées, un peu plus loin.</p>')}`},
  {h:'Assembler des limites',p:`Calcule lim ${F('4 − 1/<i>n</i>','2 + 3/<i>n</i>²')} quand <i>n</i> → ∞.`,lab:'L =',ans:2,
   why:'1/n → 0 et 3/n² → 0. Le numérateur tend vers 4, le dénominateur vers 2 ≠ 0 : la limite du quotient est 4/2 = 2.'},
  {kind:'Théorie',h:'Les limites de référence',
   p:`<p>Pour assembler, il faut des briques. Trois familles reviennent dans presque tous les calculs.</p>
${B('prop','<ul><li><b>1/<i>n</i> → 0</b> ; plus généralement 1/<i>n</i><sup><i>a</i></sup> → 0 pour tout <i>a</i> &gt; 0 (par exemple 1/√<i>n</i> → 0), et <i>n</i><sup><i>a</i></sup> → +∞.</li><li><b><i>q</i>ⁿ</b> : si |<i>q</i>| &lt; 1, <i>q</i>ⁿ → 0 ; si <i>q</i> = 1, la suite est constante égale à 1 ; si <i>q</i> &gt; 1, <i>q</i>ⁿ → +∞ ; si <i>q</i> ≤ −1, pas de limite.</li></ul>')}
${B('why','<p>1/<i>n</i> → 0 vient de la propriété d’Archimède : pour ε &gt; 0, il existe un entier <i>N</i> &gt; 1/ε, et alors 1/<i>n</i> ≤ 1/<i>N</i> &lt; ε pour <i>n</i> ≥ <i>N</i>. Pour <i>q</i> = 1 + <i>h</i> avec <i>h</i> &gt; 0, l’inégalité de Bernoulli <b>(1 + <i>h</i>)ⁿ ≥ 1 + <i>nh</i></b> (une récurrence) force <i>q</i>ⁿ → +∞. Si 0 &lt; |<i>q</i>| &lt; 1, alors 1/|<i>q</i>| &gt; 1, donc (1/|<i>q</i>|)ⁿ → +∞ et son inverse |<i>q</i>|ⁿ → 0.</p>')}
${B('ex','<p>0,9ⁿ → 0, lentement (0,9¹⁰⁰ ≈ 2,7 · 10⁻⁵). 1,01ⁿ → +∞, lentement aussi. (−1/2)ⁿ → 0 en changeant de signe à chaque pas. (−1)ⁿ vaut 1, −1, 1, −1… et n’a pas de limite.</p>')}
<p>Déplace <i>q</i> et observe les quatre comportements de <i>q</i>ⁿ.</p>`,
   params:[{id:'q',l:'q',min:-1.2,max:1.2,step:0.1,v:0.8}],
   draw:v=>seq(n=>Math.pow(v.q,n),15,{n0:0,y:[-3.2,3.2],L:0,lx:5,ly:1}).svg(),
   info:v=>{ const q=v.q; let s; if(q>1+1e-9) s='<i>q</i> &gt; 1 : la suite tend vers +∞ (elle sort vite du cadre).'; else if(Math.abs(q-1)<1e-9) s='<i>q</i> = 1 : la suite est constante, égale à 1.'; else if(Math.abs(q)<1-1e-9) s='|<i>q</i>| &lt; 1 : la suite tend vers 0'+(q<-1e-9?', en alternant de signe.':'.'); else if(Math.abs(q+1)<1e-9) s='<i>q</i> = −1 : la suite alterne entre 1 et −1, sans limite.'; else s='<i>q</i> &lt; −1 : les termes alternent de signe et grandissent en valeur absolue : pas de limite.'; return `<i>q</i> = ${fmt(q,1)}. ${s}`; }},
  {h:'Laquelle converge ?',p:'Une seule de ces suites a une limite. Laquelle&nbsp;?',opts:['(−1)ⁿ','1,001ⁿ','(−0,999)ⁿ','(−1,001)ⁿ'],ans:2,
   why:'|−0,999| = 0,999 &lt; 1, donc (−0,999)ⁿ → 0, même si le signe alterne. 1,001 &gt; 1 donne +∞ ; −1 et −1,001 sont ≤ −1 : pas de limite.'},
  {kind:'Théorie',h:'Le théorème des gendarmes',
   p:`<p>Certaines suites contiennent un terme qui refuse de converger, comme cos <i>n</i> ou (−1)ⁿ. Pourtant <i>uₙ</i> = (cos <i>n</i>)/<i>n</i> semble bien tendre vers 0. Comment le prouver sans connaître cos <i>n</i> ?</p>
${B('thm','<p>Soient trois suites telles que <b><i>aₙ</i> ≤ <i>uₙ</i> ≤ <i>bₙ</i></b> à partir d’un certain rang. Si <i>aₙ</i> → <i>L</i> et <i>bₙ</i> → <i>L</i> (la même limite), alors <i>uₙ</i> → <i>L</i>.</p>')}
${B('idea','<p>Les deux « gendarmes » (<i>aₙ</i>) et (<i>bₙ</i>) encadrent le suspect (<i>uₙ</i>) et se resserrent vers <i>L</i> : le suspect n’a nulle part où aller. Sur la figure, les points (cos <i>n</i>)/<i>n</i> restent entre les courbes 1/<i>n</i> et −1/<i>n</i>.</p>')}
${B('why','<p>Soit ε &gt; 0. À partir d’un rang <i>N</i>₁, <i>L</i> − ε &lt; <i>aₙ</i> ; à partir d’un rang <i>N</i>₂, <i>bₙ</i> &lt; <i>L</i> + ε. Pour <i>n</i> ≥ max(<i>N</i>₁, <i>N</i>₂, rang de l’encadrement), on a <i>L</i> − ε &lt; <i>aₙ</i> ≤ <i>uₙ</i> ≤ <i>bₙ</i> &lt; <i>L</i> + ε, c’est-à-dire |<i>uₙ</i> − <i>L</i>| &lt; ε. C’est exactement la définition de <i>uₙ</i> → <i>L</i>.</p>')}
${B('ex','<p>−1 ≤ cos <i>n</i> ≤ 1, donc −1/<i>n</i> ≤ (cos <i>n</i>)/<i>n</i> ≤ 1/<i>n</i>. Les deux bornes tendent vers 0, donc (cos <i>n</i>)/<i>n</i> → 0. Variante à un seul gendarme : si <i>uₙ</i> ≥ <i>aₙ</i> et <i>aₙ</i> → +∞, alors <i>uₙ</i> → +∞.</p>')}
${B('warn','<p>Les deux gendarmes doivent avoir la <b>même</b> limite. Avec −1 ≤ (−1)ⁿ ≤ 1, les bornes tendent vers −1 et 1 : on ne conclut rien, et de fait (−1)ⁿ n’a pas de limite.</p>')}`,
   fig:(()=>{ const P=seq(n=>Math.cos(n)/n,20,{y:[-1.1,1.1],L:0,h:180,c:'var(--accent)',r:4}); P.fn(x=>1/x,{from:.9,to:21,c:'var(--spark)',w:2,dash:true}).fn(x=>-1/x,{from:.9,to:21,c:'var(--spark)',w:2,dash:true}).text(16,.2,'1/n',{c:'var(--spark)'}).text(16,-.3,'−1/n',{c:'var(--spark)'}); return P.svg(); })()},
  {kind:'Théorie',h:'Passer à la limite dans une inégalité',
   p:`<p>Si tous les termes d’une suite sont inférieurs à ceux d’une autre, leurs limites gardent-elles cet ordre ? Oui, à une nuance près qui piège beaucoup de monde.</p>
${B('prop','<p>Si <i>uₙ</i> ≤ <i>vₙ</i> à partir d’un certain rang, et si <i>uₙ</i> → <i>a</i> et <i>vₙ</i> → <i>b</i>, alors <b><i>a</i> ≤ <i>b</i></b>. En particulier, si <i>uₙ</i> ≤ <i>M</i> pour tout <i>n</i>, alors <i>a</i> ≤ <i>M</i>.</p>')}
${B('why','<p>Par l’absurde : supposons <i>a</i> &gt; <i>b</i> et posons ε = (<i>a</i> − <i>b</i>)/2 &gt; 0. Pour <i>n</i> assez grand, <i>uₙ</i> &gt; <i>a</i> − ε = (<i>a</i> + <i>b</i>)/2 et <i>vₙ</i> &lt; <i>b</i> + ε = (<i>a</i> + <i>b</i>)/2. Alors <i>uₙ</i> &gt; <i>vₙ</i>, ce qui contredit l’hypothèse. Donc <i>a</i> ≤ <i>b</i>.</p>')}
${B('warn','<p>Une inégalité <b>stricte</b> ne le reste pas forcément : 1/<i>n</i> &gt; 0 pour tout <i>n</i>, mais la limite vaut 0, pas « strictement plus que 0 ». À la limite, « &lt; » devient « ≤ ».</p>')}
${B('ex','<p>Si une suite convergente vérifie 2 ≤ <i>uₙ</i> ≤ 5 pour tout <i>n</i>, sa limite est dans [2 ; 5]. Si <i>uₙ</i> ∈ ]0 ; 1[ pour tout <i>n</i>, la limite est dans [0 ; 1] : elle peut valoir 0 ou 1.</p>')}`},
  {kind:'Méthode',h:'Encadrer pour trouver une limite',
   p:'<b>Quand :</b> la suite contient un morceau borné qui n’a pas de limite (cos <i>n</i>, sin <i>n</i>, (−1)ⁿ, une partie entière…). <b>Pourquoi ça marche :</b> ce morceau est coincé entre deux constantes ; en reportant ces constantes dans l’expression, on obtient deux gendarmes dont on sait calculer les limites. <b>Comment :</b><ol><li>isole le morceau gênant et encadre-le (−1 ≤ cos <i>n</i> ≤ 1) ;</li><li>applique les mêmes opérations aux trois membres, en <b>renversant</b> le sens si tu multiplies par un négatif ;</li><li>calcule les limites des deux bornes ; si elles coïncident, conclus par les gendarmes.</li></ol>',
   demo:{enonce:'Calculer lim <i>uₙ</i> avec <i>uₙ</i> = 3 + (sin <i>n</i>)/<i>n</i>.',
    etapes:[{f:'−1 ≤ sin <i>n</i> ≤ 1 pour tout <i>n</i>.',w:'Le sinus n’a pas de limite, mais il est borné : c’est lui qu’on encadre.'},
     {f:'−1/<i>n</i> ≤ (sin <i>n</i>)/<i>n</i> ≤ 1/<i>n</i>, car <i>n</i> &gt; 0.',w:'Diviser par un nombre positif conserve le sens des inégalités.'},
     {f:'3 − 1/<i>n</i> ≤ <i>uₙ</i> ≤ 3 + 1/<i>n</i>.',w:'Ajouter 3 aux trois membres ne change rien au sens.'},
     {f:'3 − 1/<i>n</i> → 3 et 3 + 1/<i>n</i> → 3.',w:'Limite d’une somme : 1/<i>n</i> → 0.'}],
    conclusion:'Les deux gendarmes tendent vers 3, donc <i>uₙ</i> → 3. On n’a jamais eu besoin de connaître la valeur de sin <i>n</i>.'},
   note:'Si l’expression est une fraction, sépare-la d’abord : (4<i>n</i> + sin <i>n</i>)/<i>n</i> = 4 + (sin <i>n</i>)/<i>n</i>.'},
  {h:'Un sinus qui gêne',p:`Calcule lim ${F('4<i>n</i> + sin <i>n</i>','<i>n</i>')} quand <i>n</i> → ∞.`,lab:'L =',ans:4,
   why:'(4n + sin n)/n = 4 + (sin n)/n. Comme −1/n ≤ (sin n)/n ≤ 1/n et que les bornes tendent vers 0, (sin n)/n → 0 et la limite vaut 4.'},
  {kind:'Théorie',h:'Les formes indéterminées',
   p:`<p>Quand des suites tendent vers l’infini, les règles de calcul s’étendent souvent : si <i>uₙ</i> → +∞ et <i>vₙ</i> → 3, alors <i>uₙ</i> + <i>vₙ</i> → +∞, <i>uₙvₙ</i> → +∞ et <i>vₙ</i>/<i>uₙ</i> → 0. Mais quatre situations ne se décident pas d’avance.</p>
${B('def','<p>Les <b>formes indéterminées</b> sont <b>∞ − ∞</b>, <b>0 · ∞</b>, <b>∞/∞</b> et <b>0/0</b>. « Indéterminée » veut dire : connaître les limites des deux morceaux ne suffit pas pour connaître celle de l’ensemble.</p>')}
${B('ex','<p>Quatre différences de deux suites qui tendent vers +∞, quatre résultats différents :</p>'+tab(['Suite','Forme','Limite'],[['<i>n</i>² − <i>n</i> = <i>n</i>(<i>n</i> − 1)','∞ − ∞','+∞'],['<i>n</i> − <i>n</i>²','∞ − ∞','−∞'],['(<i>n</i> + 5) − <i>n</i>','∞ − ∞','5'],['(<i>n</i> + (−1)ⁿ) − <i>n</i>','∞ − ∞','aucune']]))}
${B('idea','<p>Devant une forme indéterminée, la règle est : <b>transformer l’expression</b> jusqu’à faire disparaître l’indétermination. Deux outils couvrent la plupart des cas : factoriser le terme dominant, et multiplier par la quantité conjuguée. Les deux méthodes suivantes les enseignent.</p>')}
${B('warn','<p>∞ − ∞ n’est pas 0, et ∞/∞ n’est pas 1. Ces écritures ne sont pas des nombres : ce sont des signaux d’alarme.</p>')}`},
  {kind:'Méthode',h:'Factoriser le terme dominant',
   p:'<b>Quand :</b> forme ∞/∞ ou ∞ − ∞ avec des puissances de <i>n</i> (ou des puissances <i>q</i>ⁿ). <b>Pourquoi ça marche :</b> quand on met en facteur la plus grande puissance, tous les autres termes deviennent des 1/<i>n</i>, 1/<i>n</i>², … qui tendent vers 0 : seul le terme dominant compte vraiment. <b>Comment :</b><ol><li>repère la plus grande puissance de <i>n</i> en haut et en bas ;</li><li>mets-la en facteur dans chacun, puis simplifie ;</li><li>passe à la limite avec les règles ordinaires.</li></ol>',
   demo:{enonce:`Calculer lim ${F('4<i>n</i>³ + <i>n</i>','<i>n</i>³ − 2<i>n</i>² + 7')} quand <i>n</i> → ∞.`,
    etapes:[{f:'Forme ∞/∞.',w:'Numérateur et dénominateur tendent vers +∞ : on ne peut pas conclure directement.'},
     {f:`= ${F('<i>n</i>³(4 + 1/<i>n</i>²)','<i>n</i>³(1 − 2/<i>n</i> + 7/<i>n</i>³)')}`,w:'On factorise <i>n</i>³, la plus grande puissance, en haut comme en bas.'},
     {f:`= ${F('4 + 1/<i>n</i>²','1 − 2/<i>n</i> + 7/<i>n</i>³')}`,w:'On simplifie par <i>n</i>³ ≠ 0.'},
     {f:'→ 4/1 = 4.',w:'Chaque 1/<i>n</i><sup><i>k</i></sup> tend vers 0 ; il reste le quotient des coefficients dominants.'}],
    conclusion:'La limite vaut 4. Règle générale pour deux polynômes en <i>n</i> : même degré, la limite est le quotient des coefficients dominants ; degré plus petit en haut, la limite est 0 ; degré plus grand en haut, la limite est ±∞.'},
   note:'Pour un seul polynôme, c’est pareil : <i>n</i>² − 5<i>n</i> = <i>n</i>²(1 − 5/<i>n</i>) → +∞, car <i>n</i>² → +∞ et la parenthèse → 1. Avec des puissances <i>q</i>ⁿ, on factorise celle de plus grande base : (2ⁿ + 3ⁿ)/3ⁿ = (2/3)ⁿ + 1 → 1.'},
  {h:'Même degré en haut et en bas',p:`Calcule lim ${F('6<i>n</i>² − <i>n</i> + 2','2 − 3<i>n</i>²')} quand <i>n</i> → ∞.`,lab:'L =',ans:-2,
   why:'On factorise n² : (6 − 1/n + 2/n²)/(2/n² − 3) → 6/(−3) = −2.'},
  {kind:'Défi',h:'Gendarmes et terme dominant',p:`Calcule lim ${F('<i>n</i>² + sin <i>n</i>','2<i>n</i>² + 1')} quand <i>n</i> → ∞.`,lab:'L =',ans:0.5,tol:1e-9,
   why:'−1 ≤ sin n ≤ 1 donne (n² − 1)/(2n² + 1) ≤ uₙ ≤ (n² + 1)/(2n² + 1). Chaque borne a même degré en haut et en bas : les deux tendent vers 1/2, donc uₙ → 1/2.'},
  {kind:'Méthode',h:'Multiplier par la quantité conjuguée',
   p:'<b>Quand :</b> une forme ∞ − ∞ où l’un des termes est une racine carrée, comme √(<i>n</i>² + 2<i>n</i> + 5) − <i>n</i>. Factoriser ne suffit pas : <i>n</i>(√(1 + 2/<i>n</i> + 5/<i>n</i>²) − 1) est une forme ∞ · 0. <b>Pourquoi ça marche :</b> <b>(<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>) = <i>a</i>² − <i>b</i>²</b>. Multiplier par la <b>quantité conjuguée</b> <i>a</i> + <i>b</i> fait disparaître la racine au numérateur, et le dénominateur <i>a</i> + <i>b</i> n’est plus indéterminé. <b>Comment :</b> écris la différence comme une fraction de dénominateur 1, multiplie haut et bas par le conjugué, développe le haut avec l’identité, puis factorise le terme dominant.',
   demo:{enonce:'Calculer lim (√(<i>n</i>² + 2<i>n</i> + 5) − <i>n</i>) quand <i>n</i> → ∞.',
    etapes:[{f:'Forme ∞ − ∞.',w:'La racine et <i>n</i> tendent tous deux vers +∞.'},
     {f:`= ${F('(√(<i>n</i>² + 2<i>n</i> + 5) − <i>n</i>)(√(<i>n</i>² + 2<i>n</i> + 5) + <i>n</i>)','√(<i>n</i>² + 2<i>n</i> + 5) + <i>n</i>')}`,w:'On multiplie et on divise par le conjugué : la valeur ne change pas.'},
     {f:`= ${F('<i>n</i>² + 2<i>n</i> + 5 − <i>n</i>²','√(<i>n</i>² + 2<i>n</i> + 5) + <i>n</i>')} = ${F('2<i>n</i> + 5','√(<i>n</i>² + 2<i>n</i> + 5) + <i>n</i>')}`,w:'(<i>a</i> − <i>b</i>)(<i>a</i> + <i>b</i>) = <i>a</i>² − <i>b</i>² : la racine a disparu du numérateur.'},
     {f:`= ${F('<i>n</i>(2 + 5/<i>n</i>)','<i>n</i>(√(1 + 2/<i>n</i> + 5/<i>n</i>²) + 1)')} = ${F('2 + 5/<i>n</i>','√(1 + 2/<i>n</i> + 5/<i>n</i>²) + 1')}`,w:'Sous la racine, <i>n</i>² + 2<i>n</i> + 5 = <i>n</i>²(1 + 2/<i>n</i> + 5/<i>n</i>²), et √(<i>n</i>²) = <i>n</i> car <i>n</i> &gt; 0.'},
     {f:'→ 2/(1 + 1) = 1.',w:'Plus aucune indétermination : on applique les règles ordinaires.'}],
    conclusion:'La limite vaut 1. Sans la transformation, « ∞ − ∞ » ne nous aurait rien dit.'}},
  {h:'Une racine qui s’échappe',p:'Calcule lim (√(4<i>n</i>² + <i>n</i>) − 2<i>n</i>) quand <i>n</i> → ∞. Donne une fraction ou un décimal exact.',lab:'L =',ans:0.25,tol:1e-9,
   why:'Conjugué : (4n² + n − 4n²)/(√(4n² + n) + 2n) = n/(n(√(4 + 1/n) + 2)) → 1/(2 + 2) = 1/4.'},
  {kind:'Théorie',h:'Suites adjacentes',
   p:`<p>Comment prouver qu’une suite converge quand on ne connaît pas sa limite ? Une méthode puissante consiste à la coincer entre deux suites qui se rapprochent l’une de l’autre.</p>
${B('def','<p>Deux suites (<i>aₙ</i>) et (<i>bₙ</i>) sont <b>adjacentes</b> si (<i>aₙ</i>) est croissante, (<i>bₙ</i>) est décroissante, et <b><i>bₙ</i> − <i>aₙ</i> → 0</b>.</p>')}
${B('thm','<p>Deux suites adjacentes convergent, et vers la <b>même</b> limite <i>L</i>. De plus <i>aₙ</i> ≤ <i>L</i> ≤ <i>bₙ</i> pour tout <i>n</i> : chaque couple (<i>aₙ</i>, <i>bₙ</i>) encadre la limite.</p>')}
${B('why','<p>La suite <i>bₙ</i> − <i>aₙ</i> est décroissante (on retire une suite croissante à une décroissante) et tend vers 0 : elle est donc toujours ≥ 0, c’est-à-dire <i>aₙ</i> ≤ <i>bₙ</i>. Alors <i>aₙ</i> ≤ <i>bₙ</i> ≤ <i>b</i>₀ : (<i>aₙ</i>) est croissante et majorée, donc converge vers un réel <i>L</i>. De même (<i>bₙ</i>) est décroissante et minorée par <i>a</i>₀ : elle converge vers <i>L</i>′. Enfin <i>L</i>′ − <i>L</i> = lim (<i>bₙ</i> − <i>aₙ</i>) = 0.</p>')}
${B('ex','<p><i>aₙ</i> = 2 − 2/<i>n</i> est croissante, <i>bₙ</i> = 2 + 1/<i>n</i> est décroissante, et <i>bₙ</i> − <i>aₙ</i> = 3/<i>n</i> → 0. Les segments [<i>aₙ</i> ; <i>bₙ</i>] s’emboîtent et se resserrent sur 2. Fais varier <i>n</i> pour le voir.</p>')}
${B('warn','<p>Les trois conditions comptent. <i>aₙ</i> = 1 − 1/<i>n</i> et <i>bₙ</i> = 3 + 1/<i>n</i> sont monotones dans le bon sens, mais <i>bₙ</i> − <i>aₙ</i> → 2 : elles convergent vers des limites différentes.</p>')}`,
   params:[{id:'n',l:'n',min:1,max:25,v:3}],
   draw:v=>{ const P=plane({x:[-0.4,3.6],y:[0,27],h:240,grid:false,axes:false});
     P.seg(-0.4,0.5,3.6,0.5,{c:'var(--muted)',w:1.5}); for(let k=0;k<=3;k++){ P.seg(k,0.2,k,0.8,{c:'var(--muted)',w:1.2}); P.text(k,0.5,String(k),{a:'middle',dy:16,s:11,c:'var(--muted)'}); }
     P.seg(2,0.5,2,26.5,{c:'var(--ok)',w:1.5,dash:true});
     for(let k=1;k<=v.n;k++){ const a=2-2/k,b=2+1/k; P.seg(a,k+1,b,k+1,{c:k===v.n?'var(--accent)':'var(--spark)',w:k===v.n?5:2.5,op:k===v.n?1:.6}); }
     const a=2-2/v.n,b=2+1/v.n; P.dot(a,v.n+1,{r:5,c:'var(--accent)'}).dot(b,v.n+1,{r:5,c:'var(--accent)'}); P.text(a,v.n+1,'aₙ',{a:'end',dx:-10,dy:4}).text(b,v.n+1,'bₙ',{dx:10,dy:4}); return P.svg(); },
   info:v=>`<i>n</i> = ${v.n} : <i>aₙ</i> = ${fmt(2-2/v.n,3)}, <i>bₙ</i> = ${fmt(2+1/v.n,3)}, longueur <i>bₙ</i> − <i>aₙ</i> = 3/${v.n} = ${fmt(3/v.n,3)}.`},
  {h:'Adjacentes ou pas ?',p:'Un seul de ces couples est formé de deux suites adjacentes (dans l’ordre (<i>aₙ</i>), (<i>bₙ</i>)). Lequel&nbsp;?',
   opts:['<i>aₙ</i> = 1/<i>n</i> et <i>bₙ</i> = 2/<i>n</i>','<i>aₙ</i> = −1/<i>n</i> et <i>bₙ</i> = 1/<i>n</i>','<i>aₙ</i> = 1 − 1/<i>n</i> et <i>bₙ</i> = 3 + 1/<i>n</i>','<i>aₙ</i> = <i>n</i> et <i>bₙ</i> = <i>n</i> + 1/<i>n</i>'],ans:1,
   why:'−1/n est croissante, 1/n est décroissante et leur différence 2/n tend vers 0 : adjacentes, de limite commune 0. Dans le 1er couple, aₙ décroît ; dans le 3e, la différence tend vers 2 ; dans le 4e, bₙ croît et les deux suites divergent.'},
  {kind:'Théorie',h:'Un réel, limite de ses troncatures',
   p:`<p>Écrire √2 = 1,41421356… , c’est en réalité parler d’une suite. Le <b>développement décimal</b> d’un réel <i>x</i> ≥ 0 est la suite de ses <b>troncatures</b> : <i>d</i>₀ = 1, <i>d</i>₁ = 1,4, <i>d</i>₂ = 1,41, <i>d</i>₃ = 1,414…</p>
${B('def','<p>La troncature à <i>n</i> décimales de <i>x</i> est <i>dₙ</i> = ⌊10ⁿ<i>x</i>⌋ / 10ⁿ : le plus grand nombre à <i>n</i> décimales qui ne dépasse pas <i>x</i>. On a <b><i>dₙ</i> ≤ <i>x</i> &lt; <i>dₙ</i> + 10⁻ⁿ</b>.</p>')}
${B('prop','<p>La suite (<i>dₙ</i>) est croissante, et <i>dₙ</i> → <i>x</i>. Tout réel est la limite de ses troncatures : les décimales ne « sont » pas le nombre, elles l’approchent aussi près qu’on veut.</p>')}
${B('why','<p>Chaque troncature ajoute un chiffre sans toucher aux précédents, donc <i>dₙ</i>₊₁ ≥ <i>dₙ</i>. Et l’encadrement <i>dₙ</i> ≤ <i>x</i> &lt; <i>dₙ</i> + 10⁻ⁿ donne 0 ≤ <i>x</i> − <i>dₙ</i> &lt; 10⁻ⁿ = (1/10)ⁿ → 0 : par les gendarmes, <i>x</i> − <i>dₙ</i> → 0.</p>')}
${B('ex','<p>0,999… désigne la limite de la suite 0,9 ; 0,99 ; 0,999 ; … dont le terme général est <i>uₙ</i> = 1 − 10⁻ⁿ. Comme 10⁻ⁿ → 0, cette limite vaut exactement 1 : <b>0,999… = 1</b>. Ce n’est pas une approximation, c’est une égalité, parce qu’une écriture infinie désigne une limite.</p>')}
${B('warn','<p>Un nombre décimal a donc <b>deux</b> écritures infinies : 0,25 = 0,25000… = 0,24999…. La troncature choisit toujours la première (celle qui finit par des 0).</p>')}
<p>La figure zoome sur l’intervalle [<i>dₙ</i> ; <i>dₙ</i> + 10⁻ⁿ[ qui contient √2 ; la zone colorée est l’intervalle suivant.</p>`,
   params:[{id:'n',l:'nombre de décimales n',min:0,max:5,v:1}],
   draw:v=>{ const s2=Math.SQRT2, p=Math.pow(10,v.n), d=fl(s2*p)/p, d1=fl(s2*p*10)/(p*10), t=(s2-d)*p, t1=(d1-d)*p;
     const P=plane({x:[-0.15,1.15],y:[-0.45,0.5],h:130,grid:false,axes:false});
     P.rect(t1,-0.08,0.1,0.16,{fill:'var(--spark)',fo:.4,c:null}); P.seg(0,0,1,0,{c:'var(--muted)',w:2});
     for(let k=0;k<=10;k++) P.seg(k/10,-0.06,k/10,0.06,{c:'var(--muted)',w:1.2});
     P.text(0,0,d.toFixed(v.n).replace('.',','),{a:'middle',dy:26,s:12}).text(1,0,(d+1/p).toFixed(v.n).replace('.',','),{a:'middle',dy:26,s:12});
     P.dot(t,0,{r:6,c:'var(--accent)',l:'√2',dy:-12,dx:-8}); return P.svg(); },
   info:v=>{ const p=Math.pow(10,v.n), d=fl(Math.SQRT2*p)/p; return `<i>d</i><sub>${v.n}</sub> = ${d.toFixed(v.n).replace('.',',')} ≤ √2 &lt; ${(d+1/p).toFixed(v.n).replace('.',',')} : l’erreur est inférieure à 10<sup>−${v.n}</sup>.`; }},
  {kind:'Méthode',h:'Développement périodique et fraction',
   p:'<b>Le fait :</b> un réel est <b>rationnel</b> si et seulement si son développement décimal est <b>périodique</b> à partir d’un certain rang (une écriture finie compte comme périodique, de période 0). <b>Pourquoi, sens direct :</b> en posant la division de <i>p</i> par <i>q</i>, chaque reste est dans {0, 1, …, <i>q</i> − 1}. Après au plus <i>q</i> étapes, un reste revient, et à partir de là les chiffres se répètent : la période compte au plus <i>q</i> − 1 chiffres. <b>Sens réciproque, et comment calculer :</b> si <i>x</i> a une période de <i>k</i> chiffres, alors 10<sup><i>k</i></sup><i>x</i> et <i>x</i> ont les mêmes décimales ; leur différence est un entier (ou un décimal), ce qui donne <i>x</i> sous forme de fraction.<ol><li>Repère la longueur <i>k</i> de la période.</li><li>Calcule 10<sup><i>k</i></sup><i>x</i> − <i>x</i> : les parties décimales s’annulent.</li><li>Résous, puis simplifie la fraction.</li></ol>',
   demo:{enonce:'Écrire <i>x</i> = 0,272727… sous forme de fraction irréductible.',
    etapes:[{f:'La période est « 27 », de longueur <i>k</i> = 2.',w:'Les chiffres se répètent par blocs de deux.'},
     {f:'100<i>x</i> = 27,272727…',w:'Multiplier par 10² décale la virgule de deux rangs : la partie décimale est la même que celle de <i>x</i>.'},
     {f:'100<i>x</i> − <i>x</i> = 27,2727… − 0,2727… = 27, donc 99<i>x</i> = 27.',w:'Les parties décimales identiques s’annulent ; il reste un entier.'},
     {f:'<i>x</i> = 27/99 = 3/11.',w:'On simplifie par 9.'}],
    conclusion:'0,272727… = 3/11. Vérification : 3 ÷ 11 donne les restes 3, 8, 3, 8… et les chiffres 2, 7, 2, 7…'},
   note:'Si la période ne commence pas tout de suite, décale d’abord : <i>x</i> = 0,8333… donne 10<i>x</i> = 8,333… et 100<i>x</i> = 83,333…, donc 90<i>x</i> = 75 et <i>x</i> = 75/90 = 5/6.'},
  {h:'De la période à la fraction',p:'On écrit <i>x</i> = 0,454545… sous la forme <i>p</i>/<i>q</i> avec <i>p</i>/<i>q</i> irréductible. Que vaut <i>q</i>&nbsp;?',lab:'q =',ans:11,
   why:'Période « 45 » : 100x − x = 45, donc x = 45/99 = 5/11. Le dénominateur réduit est 11.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`${B('keep','<ul><li><b>Opérations</b> : si <i>uₙ</i> → <i>a</i> et <i>vₙ</i> → <i>b</i> (finies), somme → <i>a</i> + <i>b</i>, produit → <i>ab</i>, quotient → <i>a</i>/<i>b</i> si <i>b</i> ≠ 0. Preuve de la somme : ε/2 pour chacune.</li><li><b>Références</b> : 1/<i>n</i><sup><i>a</i></sup> → 0 et <i>n</i><sup><i>a</i></sup> → +∞ pour <i>a</i> &gt; 0 ; <i>q</i>ⁿ → 0 si |<i>q</i>| &lt; 1, → +∞ si <i>q</i> &gt; 1, pas de limite si <i>q</i> ≤ −1.</li><li><b>Gendarmes</b> : <i>aₙ</i> ≤ <i>uₙ</i> ≤ <i>bₙ</i> et <i>aₙ</i>, <i>bₙ</i> → <i>L</i> ⇒ <i>uₙ</i> → <i>L</i>. Passage à la limite : <i>uₙ</i> ≤ <i>vₙ</i> ⇒ lim <i>uₙ</i> ≤ lim <i>vₙ</i> (le strict devient large).</li><li><b>Formes indéterminées</b> : ∞ − ∞, 0 · ∞, ∞/∞, 0/0. Remèdes : factoriser le terme dominant (quotient des coefficients dominants si mêmes degrés) ; quantité conjuguée quand une racine est en jeu.</li><li><b>Suites adjacentes</b> : (<i>aₙ</i>) croissante, (<i>bₙ</i>) décroissante, <i>bₙ</i> − <i>aₙ</i> → 0 ⇒ même limite <i>L</i>, avec <i>aₙ</i> ≤ <i>L</i> ≤ <i>bₙ</i>.</li><li><b>Décimaux</b> : un réel est la limite de ses troncatures ; 0,999… = 1 ; développement périodique ⇔ rationnel, et 10<sup><i>k</i></sup><i>x</i> − <i>x</i> donne la fraction.</li></ul>')}`},
  {kind:'Problème',h:'Encadrer l’aire sous une parabole',
   p:'On veut mesurer l’aire sous la courbe <i>y</i> = <i>x</i>² entre <i>x</i> = 0 et <i>x</i> = 1. On découpe [0 ; 1] en <i>n</i> tranches de largeur 1/<i>n</i>. Avec des rectangles qui restent sous la courbe, on obtient l’aire <i>aₙ</i> = (0² + 1² + … + (<i>n</i> − 1)²)/<i>n</i>³ ; avec des rectangles qui dépassent, <i>bₙ</i> = (1² + 2² + … + <i>n</i>²)/<i>n</i>³. On admet la formule 1² + 2² + … + <i>k</i>² = <i>k</i>(<i>k</i> + 1)(2<i>k</i> + 1)/6, qui donne <i>aₙ</i> = (<i>n</i> − 1)(2<i>n</i> − 1)/(6<i>n</i>²) et <i>bₙ</i> = (<i>n</i> + 1)(2<i>n</i> + 1)/(6<i>n</i>²). On admet aussi que (<i>aₙ</i>) est croissante et (<i>bₙ</i>) décroissante.',
   fig:(()=>{ const P=plane({x:[-0.15,1.15],y:[-0.1,1.1],h:220,grid:false,lab:1}); const n=5; for(let k=0;k<n;k++){ P.rect(k/n,0,1/n,(k/n)**2,{fill:'var(--accent)',fo:.35,c:'var(--accent)',w:1}); P.rect(k/n,(k/n)**2,1/n,((k+1)/n)**2-(k/n)**2,{fill:'var(--spark)',fo:.3,c:'var(--spark)',w:1}); } P.fn(x=>x*x,{from:0,to:1.05,c:'var(--ink)',w:2.5}); return P.svg(); })(),
   parts:[
    {q:'a) Que vaut <i>a</i>₃&nbsp;? Donne une fraction ou un arrondi au millième.',lab:'a₃ =',ans:5/27,tol:5e-4,hint:'Remplace n par 3 dans (n − 1)(2n − 1)/(6n²).',why:'a₃ = (2 · 5)/(6 · 9) = 10/54 = 5/27 ≈ 0,185.'},
    {q:'b) Que vaut <i>bₙ</i> − <i>aₙ</i> après simplification&nbsp;?',opts:['1/<i>n</i>','2/<i>n</i>','1/(6<i>n</i>²)','6/<i>n</i>'],ans:0,hint:'Développe (n + 1)(2n + 1) et (n − 1)(2n − 1), puis soustrais.',why:'(2n² + 3n + 1) − (2n² − 3n + 1) = 6n, et 6n/(6n²) = 1/n.'},
    {q:'c) Pourquoi (<i>aₙ</i>) et (<i>bₙ</i>) convergent-elles vers la même limite, et laquelle&nbsp;? Donne cette limite (fraction ou arrondi au millième).',lab:'L =',ans:1/3,tol:5e-4,hint:'Elles sont adjacentes. Pour la limite, factorise le terme dominant dans aₙ.',why:'(aₙ) croissante, (bₙ) décroissante, bₙ − aₙ = 1/n → 0 : adjacentes. Et aₙ = (2n² − 3n + 1)/(6n²) → 2/6 = 1/3.'},
    {q:'d) À partir de quel rang <i>N</i> l’encadrement <i>aₙ</i> ≤ <i>L</i> ≤ <i>bₙ</i> donne-t-il l’aire à moins de 0,01 près, c’est-à-dire <i>bₙ</i> − <i>aₙ</i> &lt; 0,01&nbsp;?',lab:'N =',ans:101,hint:'bₙ − aₙ = 1/n. Attention à l’inégalité stricte.',why:'1/n &lt; 0,01 ⇔ n &gt; 100. Le premier rang qui convient est N = 101 (pour n = 100, l’écart vaut exactement 0,01).'},
   ],
   sol:'a₃ = (3 − 1)(6 − 1)/(6 · 9) = 10/54 = 5/27.<br>bₙ − aₙ = [(n + 1)(2n + 1) − (n − 1)(2n − 1)]/(6n²) = 6n/(6n²) = 1/n → 0. Avec (aₙ) croissante et (bₙ) décroissante, les deux suites sont adjacentes : elles convergent vers une même limite L, et aₙ ≤ L ≤ bₙ pour tout n.<br>En factorisant n² : aₙ = (2 − 3/n + 1/n²)/6 → 1/3. L’aire sous la parabole vaut donc <b>1/3</b>.<br>L’encadrement a pour largeur 1/n, inférieure à 0,01 dès que n ≥ 101. C’est la première rencontre avec l’intégrale : une aire définie comme limite commune de deux suites adjacentes.'},
  {kind:'Problème',h:'Les décimales de 1/7',
   p:'La division de 1 par 7 donne 1/7 = 0,142857 142857 142857… On veut comprendre pourquoi ces chiffres se répètent, en tirer des informations précises, puis comparer avec un nombre dont les décimales ne se répètent jamais : <i>y</i> = 0,101001000100001… (après chaque 1, on écrit un 0 de plus qu’avant).',
   parts:[
    {q:'a) Quelle est la longueur de la période de 1/7&nbsp;?',lab:'longueur :',ans:6,hint:'Compte les chiffres du bloc qui se répète.',why:'Le bloc 142857 compte 6 chiffres. C’est le maximum possible pour un dénominateur 7 : il y a 6 restes non nuls possibles (1 à 6), et ils apparaissent tous.'},
    {q:'b) Quelle est la 22<sup>e</sup> décimale de 1/7&nbsp;?',lab:'chiffre :',ans:8,hint:'22 = 3 · 6 + 4 : la 22e décimale est la 4e du bloc.',why:'Les décimales se répètent par blocs de 6. 22 = 18 + 4, donc la 22e décimale est la 4e du bloc 142857 : c’est 8.'},
    {q:'c) Pourquoi le développement d’un rationnel <i>p</i>/<i>q</i> est-il toujours périodique&nbsp;?',opts:['Parce que tous les réels ont un développement périodique','Parce que la division posée n’a que q restes possibles : un reste revient, et les chiffres suivants aussi','Parce que les chiffres sont au nombre de 10','Parce que p/q est plus petit que 1'],ans:1,hint:'Pense à la division posée : que se passe-t-il quand un reste déjà vu réapparaît ?',why:'Les restes sont dans {0, …, q − 1}. Après au plus q étapes, un reste réapparaît, et la division recommence à l’identique : les chiffres se répètent.'},
    {q:'d) En appliquant la méthode 10<sup><i>k</i></sup><i>x</i> − <i>x</i> à <i>x</i> = 0,142857142857…, on trouve <i>x</i> = 142857/999999. Quel est le dénominateur de la fraction irréductible&nbsp;?',lab:'q =',ans:7,hint:'Tu connais déjà la valeur de x. Vérifie que 142857 · 7 = 999999.',why:'10⁶x − x = 142857, donc x = 142857/999999. Comme 142857 · 7 = 999999, la fraction se simplifie en 1/7 : dénominateur 7.'},
    {q:'e) Le nombre <i>y</i> = 0,101001000100001… est-il rationnel&nbsp;?',opts:['Oui, car ses décimales ne comportent que des 0 et des 1','Oui, car il a une infinité de décimales','Non : les blocs de 0 s’allongent sans fin, donc le développement n’est jamais périodique','On ne peut pas savoir sans calculer plus de décimales'],ans:2,hint:'Un développement périodique répète le même bloc à partir d’un rang. Est-ce possible si les blocs de 0 grandissent toujours ?',why:'Si y était périodique de période k à partir d’un rang, aucune suite de plus de k zéros consécutifs ne pourrait apparaître ensuite. Or les blocs de 0 dépassent toute longueur : y est irrationnel.'},
   ],
   sol:'En posant 1 ÷ 7, les restes successifs sont 1, 3, 2, 6, 4, 5 puis de nouveau 1 : six restes, donc une période de 6 chiffres, 142857. La 22<sup>e</sup> décimale est la 4<sup>e</sup> du bloc (22 = 3 · 6 + 4), soit 8.<br>Tout rationnel p/q a un développement périodique, car les restes de la division sont au plus q et finissent par se répéter. Réciproquement, 10⁶x − x = 142857 donne x = 142857/999999 = 1/7.<br>Le nombre y = 0,101001000100001… contient des blocs de 0 de longueur 1, 2, 3, 4… Un développement périodique de période k ne peut pas contenir plus de k zéros consécutifs à partir d’un certain rang (sinon la période serait 0). Donc y n’est pas périodique : <b>y est irrationnel</b>. C’est un moyen simple de fabriquer des irrationnels explicites.'},
]},
/* ===================== 2. FONCTIONS RÉELLES : RAPPELS ET RÉPERTOIRE ===================== */
{subj:'gred',sem:'ana',id:'gred-fonctions-reelles',h:'Fonctions réelles : rappels et répertoire',p:'Domaine de définition, image, graphe, injectivité lue sur le graphe, restriction et réciproque, puis les fonctions d’usage courant et comment les reconnaître.',steps:[
  {kind:'Théorie',h:'Une fonction réelle d’une variable réelle',
   p:`<p>L’analyse étudie des quantités qui dépendent d’autres quantités : la température selon l’heure, l’aire d’un carré selon son côté. L’outil est la fonction, un cas particulier des applications déjà rencontrées.</p>
${RP('<p>Une application <i>f</i> : <i>E</i> → <i>F</i> associe à chaque élément <i>x</i> de <i>E</i> un unique élément <i>f</i>(<i>x</i>) de <i>F</i>, son image. L’ensemble de départ fait partie de la définition.</p>')}
${B('def','<p>Une <b>fonction réelle d’une variable réelle</b> est une application <i>f</i> : <i>D</i> → ℝ, où <i>D</i> est une partie de ℝ appelée <b>domaine de définition</b>. On écrit <i>f</i> : <i>x</i> ↦ <i>f</i>(<i>x</i>), et on lit « <i>x</i> a pour image <i>f</i>(<i>x</i>) ».</p>')}
${B('idea','<p>Pense à une machine : on introduit un réel <i>x</i> admis par la machine (<i>x</i> ∈ <i>D</i>), il en ressort un seul réel <i>f</i>(<i>x</i>). Deux fonctions sont égales si elles ont le même domaine et donnent la même sortie pour chaque entrée.</p>')}
${B('ex','<p><i>f</i> : ℝ → ℝ, <i>x</i> ↦ 2<i>x</i> − 1. Alors <i>f</i>(3) = 5, <i>f</i>(−1/2) = −2 et <i>f</i>(<i>t</i> + 1) = 2<i>t</i> + 1. La lettre employée pour la variable n’a pas d’importance : <i>x</i> ↦ 2<i>x</i> − 1 et <i>t</i> ↦ 2<i>t</i> − 1 sont la même fonction.</p>')}
${B('warn','<p><i>f</i> est la fonction ; <i>f</i>(<i>x</i>) est un nombre, l’image de <i>x</i>. On dit « la fonction <i>f</i> » ou « la fonction <i>x</i> ↦ <i>x</i>² », pas « la fonction <i>x</i>² ».</p>')}`},
  {kind:'Théorie',h:'Le domaine de définition naturel',
   p:`<p>Souvent on donne seulement une formule, comme <i>f</i>(<i>x</i>) = √(<i>x</i> − 1)/(<i>x</i> − 3), sans préciser le domaine. Il faut alors le déterminer soi-même.</p>
${B('def','<p>Le <b>domaine de définition naturel</b> d’une formule est l’ensemble des réels <i>x</i> pour lesquels le calcul de <i>f</i>(<i>x</i>) a un sens. Deux obstacles pour l’instant : on ne divise pas par 0, et on ne prend pas la racine carrée d’un nombre strictement négatif.</p>')}
${B('idea','<p>On lit la formule de l’intérieur vers l’extérieur et on note chaque condition : chaque dénominateur doit être non nul, chaque radicande (ce qui est sous la racine) doit être ≥ 0. Le domaine est l’ensemble des <i>x</i> qui vérifient <b>toutes</b> ces conditions à la fois.</p>')}
${B('ex','<p>Pour <i>f</i>(<i>x</i>) = √(<i>x</i> − 1)/(<i>x</i> − 3) : il faut <i>x</i> − 1 ≥ 0, soit <i>x</i> ≥ 1, et <i>x</i> − 3 ≠ 0, soit <i>x</i> ≠ 3. Donc <i>D</i> = [1 ; 3[ ∪ ]3 ; +∞[.</p>')}
${B('warn','<p>Une racine n’impose pas toujours une restriction : √(<i>x</i>² + 1) est définie sur ℝ tout entier, car <i>x</i>² + 1 &gt; 0 pour tout <i>x</i>. Vérifie le signe réel du radicande au lieu d’exclure par réflexe.</p>')}`},
  {kind:'Méthode',h:'Déterminer un domaine de définition',
   p:'<b>Quand :</b> on donne une formule sans domaine, ou on demande « sur quel ensemble <i>f</i> est-elle définie ? ». <b>Pourquoi ça marche :</b> une formule a un sens exactement quand chacune de ses opérations en a un ; le domaine est l’intersection des conditions. <b>Comment :</b><ol><li>écris une condition par dénominateur (≠ 0) et par racine carrée (radicande ≥ 0 ; &gt; 0 si la racine est au dénominateur) ;</li><li>résous chaque condition ;</li><li>garde les <i>x</i> qui les vérifient toutes, et écris le résultat avec des intervalles.</li></ol>',
   demo:{enonce:`Déterminer le domaine de définition de <i>f</i>(<i>x</i>) = ${F('√(2<i>x</i> + 6)','<i>x</i>² − 4')}.`,
    etapes:[{f:'Conditions : 2<i>x</i> + 6 ≥ 0 et <i>x</i>² − 4 ≠ 0.',w:'Une racine au numérateur (radicande ≥ 0) et un dénominateur (≠ 0).'},
     {f:'2<i>x</i> + 6 ≥ 0 ⇔ <i>x</i> ≥ −3.',w:'On résout l’inéquation du premier degré.'},
     {f:'<i>x</i>² − 4 = (<i>x</i> − 2)(<i>x</i> + 2) ≠ 0 ⇔ <i>x</i> ≠ 2 et <i>x</i> ≠ −2.',w:'Un produit est nul si et seulement si un facteur est nul.'},
     {f:'<i>D</i> = [−3 ; −2[ ∪ ]−2 ; 2[ ∪ ]2 ; +∞[.',w:'On part de [−3 ; +∞[ et on retire les deux valeurs interdites, qui sont bien dans cet intervalle.'}],
    conclusion:'Le domaine est [−3 ; −2[ ∪ ]−2 ; 2[ ∪ ]2 ; +∞[. Les crochets tournés vers l’extérieur marquent les valeurs exclues.'},
   note:'Si une valeur interdite tombe en dehors de la zone autorisée par la racine, elle ne change rien : pour √(<i>x</i> − 5)/(<i>x</i> + 1), la condition <i>x</i> ≠ −1 est automatique quand <i>x</i> ≥ 5.'},
  {h:'Où la formule a-t-elle un sens ?',p:`Quel est le domaine de définition naturel de <i>f</i>(<i>x</i>) = ${F('<i>x</i> + 1','√(3 − <i>x</i>)')}&nbsp;?`,
   opts:[']−∞ ; 3]',']−∞ ; 3[','[3 ; +∞[','ℝ privé de 3'],ans:1,
   why:'La racine est au dénominateur : il faut 3 − x &gt; 0 strictement, soit x &lt; 3. Le domaine est ]−∞ ; 3[ ; en 3, on diviserait par √0 = 0.'},
  {kind:'Théorie',h:'Image et graphe',
   p:`<p>Deux objets résument une fonction : l’ensemble des valeurs qu’elle prend, et son dessin.</p>
${B('def','<p>L’<b>image</b> de <i>f</i> est <i>f</i>(<i>D</i>) = {<i>f</i>(<i>x</i>) ; <i>x</i> ∈ <i>D</i>}, l’ensemble des valeurs effectivement atteintes. Le <b>graphe</b> de <i>f</i> est l’ensemble Γ<sub><i>f</i></sub> = {(<i>x</i> ; <i>f</i>(<i>x</i>)) ; <i>x</i> ∈ <i>D</i>} des points du plan de coordonnées (<i>x</i> ; <i>f</i>(<i>x</i>)).</p>')}
${B('idea','<p>Sur le graphe, le domaine se lit sur l’axe horizontal (les abscisses des points), l’image sur l’axe vertical (leurs ordonnées). Une courbe est le graphe d’une fonction si et seulement si <b>toute droite verticale</b> <i>x</i> = <i>c</i> la coupe en au plus un point : un cercle n’est pas un graphe.</p>')}
${B('ex','<p><i>f</i>(<i>x</i>) = <i>x</i>² − 2<i>x</i> = (<i>x</i> − 1)² − 1 est définie sur ℝ. Comme (<i>x</i> − 1)² ≥ 0 et vaut 0 en <i>x</i> = 1, l’image est [−1 ; +∞[. Sur la figure, déplace <i>x</i> : le point (<i>x</i> ; <i>f</i>(<i>x</i>)) parcourt la courbe et son ordonnée ne descend jamais sous −1.</p>')}
${B('warn','<p>L’image n’est pas l’ensemble d’arrivée. Pour <i>f</i> : ℝ → ℝ, <i>x</i> ↦ <i>x</i>², l’ensemble d’arrivée est ℝ mais l’image est [0 ; +∞[.</p>')}`,
   params:[{id:'x',l:'x',min:-1.5,max:3.5,step:0.25,v:2.5}],
   draw:v=>{ const f=x=>x*x-2*x, P=graph(f,{x:[-2,4],y:[-2,4],h:260}); P.seg(v.x,0,v.x,f(v.x),{c:'var(--muted)',w:1.5,dash:true}).seg(0,f(v.x),v.x,f(v.x),{c:'var(--muted)',w:1.5,dash:true}); P.seg(0,-1,0,4,{c:'var(--ok)',w:6,op:.35}); P.dot(v.x,f(v.x),{r:6,l:'(x ; f(x))'}); return P.svg(); },
   info:v=>`<i>x</i> = ${fmt(v.x)} : <i>f</i>(<i>x</i>) = ${fmt(v.x*v.x-2*v.x,3)}. La bande verte sur l’axe vertical est l’image [−1 ; +∞[.`},
  {kind:'Théorie',h:'Injectivité et surjectivité lues sur le graphe',
   p:`${RP('<p><i>f</i> : <i>D</i> → <i>F</i> est <b>injective</b> si deux réels distincts ont toujours des images distinctes (<i>f</i>(<i>x</i>₁) = <i>f</i>(<i>x</i>₂) ⇒ <i>x</i>₁ = <i>x</i>₂), <b>surjective</b> si tout élément de <i>F</i> est l’image d’au moins un <i>x</i>, <b>bijective</b> si elle est les deux.</p>')}
${B('idea','<p>Ces notions se lisent avec les <b>droites horizontales</b> <i>y</i> = <i>c</i>. Le nombre de points d’intersection avec le graphe est le nombre d’antécédents de <i>c</i>. <i>f</i> est injective si chaque horizontale coupe le graphe <b>au plus une fois</b> ; <i>f</i> : <i>D</i> → <i>F</i> est surjective si chaque horizontale <i>y</i> = <i>c</i> avec <i>c</i> ∈ <i>F</i> coupe le graphe <b>au moins une fois</b>.</p>')}
${B('ex','<p>Pour <i>f</i>(<i>x</i>) = <i>x</i>² − 2<i>x</i> sur ℝ, à valeurs dans ℝ : la droite <i>y</i> = 3 coupe le graphe en deux points (<i>x</i> = −1 et <i>x</i> = 3), donc <i>f</i> n’est pas injective ; la droite <i>y</i> = −2 ne le coupe pas, donc <i>f</i> n’est pas surjective sur ℝ. Déplace <i>c</i> pour compter.</p>')}
${B('warn','<p>Ces propriétés dépendent des ensembles choisis. La même formule <i>x</i>² est injective sur [0 ; +∞[ et surjective de ℝ sur [0 ; +∞[. La question « <i>f</i> est-elle injective ? » n’a de sens qu’avec un domaine précisé.</p>')}`,
   params:[{id:'c',l:'c (droite y = c)',min:-2,max:4,step:0.5,v:1}],
   draw:v=>{ const f=x=>x*x-2*x, P=graph(f,{x:[-2,4],y:[-2,4],h:260}); P.seg(-2,v.c,4,v.c,{c:'var(--spark)',w:2}); if(v.c>=-1){ const r=Math.sqrt(1+v.c); P.dot(1-r,v.c,{r:5}).dot(1+r,v.c,{r:5}); } return P.svg(); },
   info:v=>{ const k=v.c<-1?0:v.c===-1?1:2; return `<i>y</i> = ${fmt(v.c)} : ${k} antécédent${k>1?'s':''}. ${k===0?'Aucun : c n’est pas dans l’image, f n’est pas surjective sur ℝ.':k===1?'Un seul : c = −1 est le minimum.':'Deux : f n’est pas injective.'}`; }},
  {h:'Qui est injective ?',p:'Une seule de ces fonctions, définie sur ℝ, est injective. Laquelle&nbsp;?',
   opts:['<i>x</i> ↦ <i>x</i>²','<i>x</i> ↦ |<i>x</i>|','<i>x</i> ↦ 2<i>x</i> − 5','<i>x</i> ↦ cos <i>x</i>'],ans:2,
   why:'2x₁ − 5 = 2x₂ − 5 ⇒ x₁ = x₂ : injective. Les trois autres donnent la même image à deux réels différents : f(−1) = f(1) pour x² et |x|, cos 0 = cos 2π.'},
  {kind:'Théorie',h:'Restreindre une fonction',
   p:`<p>Une fonction non injective sur ℝ peut le devenir si on se contente d’une partie du domaine. C’est l’opération de restriction, indispensable pour parler de réciproque.</p>
${B('def','<p>Si <i>f</i> : <i>D</i> → ℝ et <i>A</i> ⊂ <i>D</i>, la <b>restriction</b> de <i>f</i> à <i>A</i>, notée <i>f</i>|<sub><i>A</i></sub>, est la fonction <i>A</i> → ℝ, <i>x</i> ↦ <i>f</i>(<i>x</i>) : même formule, domaine plus petit.</p>')}
${B('idea','<p>Sur le graphe, restreindre revient à ne garder que la partie de la courbe au-dessus de <i>A</i>. On choisit <i>A</i> pour que chaque horizontale ne coupe plus qu’une fois. On peut aussi rétrécir l’ensemble d’arrivée jusqu’à l’image pour rendre la fonction surjective.</p>')}
${B('ex','<p><i>x</i> ↦ <i>x</i>² n’est pas injective sur ℝ, mais sa restriction à [0 ; +∞[ l’est : si 0 ≤ <i>a</i> &lt; <i>b</i>, alors <i>b</i>² − <i>a</i>² = (<i>b</i> − <i>a</i>)(<i>b</i> + <i>a</i>) &gt; 0, donc <i>a</i>² ≠ <i>b</i>². Son image est [0 ; +∞[. Ainsi <i>x</i> ↦ <i>x</i>² est une <b>bijection</b> de [0 ; +∞[ sur [0 ; +∞[.</p>')}
${B('warn','<p>Le choix de <i>A</i> n’est pas unique : la restriction de <i>x</i>² à ]−∞ ; 0] est aussi injective. Chaque choix donnera une réciproque différente (ici √<i>y</i> ou −√<i>y</i>).</p>')}`},
  {kind:'Théorie',h:'Fonction réciproque et symétrie des graphes',
   p:`<p>Quand <i>f</i> : <i>D</i> → <i>F</i> est bijective, chaque <i>y</i> de <i>F</i> a exactement un antécédent : on peut « remonter » la machine.</p>
${B('def','<p>La <b>fonction réciproque</b> de la bijection <i>f</i> est <i>f</i><sup>−1</sup> : <i>F</i> → <i>D</i>, qui à <i>y</i> associe son unique antécédent. Autrement dit : <b><i>y</i> = <i>f</i>(<i>x</i>) ⇔ <i>x</i> = <i>f</i><sup>−1</sup>(<i>y</i>)</b>. On a <i>f</i><sup>−1</sup>(<i>f</i>(<i>x</i>)) = <i>x</i> et <i>f</i>(<i>f</i><sup>−1</sup>(<i>y</i>)) = <i>y</i>.</p>')}
${B('prop','<p>Le graphe de <i>f</i><sup>−1</sup> est le <b>symétrique</b> du graphe de <i>f</i> par rapport à la droite d’équation <i>y</i> = <i>x</i> (la première bissectrice).</p>')}
${B('why','<p>Le point (<i>a</i> ; <i>b</i>) est sur le graphe de <i>f</i> ⇔ <i>b</i> = <i>f</i>(<i>a</i>) ⇔ <i>a</i> = <i>f</i><sup>−1</sup>(<i>b</i>) ⇔ le point (<i>b</i> ; <i>a</i>) est sur le graphe de <i>f</i><sup>−1</sup>. Or échanger les deux coordonnées, c’est exactement la symétrie par rapport à la droite <i>y</i> = <i>x</i> : le milieu de (<i>a</i> ; <i>b</i>) et (<i>b</i> ; <i>a</i>) est sur cette droite, et le segment qui les joint lui est perpendiculaire.</p>')}
${B('ex','<p><i>f</i>(<i>x</i>) = <i>x</i>² sur [0 ; +∞[ a pour réciproque <i>f</i><sup>−1</sup>(<i>y</i>) = √<i>y</i> : la demi-parabole et la courbe de la racine sont symétriques l’une de l’autre (figure). Pour <i>f</i>(<i>x</i>) = 2<i>x</i> − 1 sur ℝ, <i>f</i><sup>−1</sup>(<i>y</i>) = (<i>y</i> + 1)/2.</p>')}
${B('warn','<p><i>f</i><sup>−1</sup> n’est <b>pas</b> 1/<i>f</i>. Pour <i>f</i>(<i>x</i>) = 2<i>x</i>, la réciproque est <i>y</i> ↦ <i>y</i>/2, alors que 1/<i>f</i>(<i>x</i>) = 1/(2<i>x</i>).</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-0.5,4],y:[-0.5,4],h:260}); P.fn(x=>x*x,{from:0,to:2.1}).fn(Math.sqrt,{from:0,to:4,c:'var(--spark)'}).fn(x=>x,{c:'var(--muted)',w:1.5,dash:true}); P.dot(1.5,2.25,{r:5,l:'(1,5 ; 2,25)'}).dot(2.25,1.5,{r:5,c:'var(--spark)',l:'(2,25 ; 1,5)',dy:16}); P.text(1.1,3.6,'y = x²').text(3.2,1.3,'y = √x',{c:'var(--spark)'}); return P.svg(); })()},
  {kind:'Méthode',h:'Trouver l’expression d’une réciproque',
   p:'<b>Quand :</b> on demande <i>f</i><sup>−1</sup>, ou de prouver que <i>f</i> est bijective de <i>D</i> sur <i>F</i>. <b>Pourquoi ça marche :</b> <i>f</i><sup>−1</sup>(<i>y</i>) est l’unique solution <i>x</i> de l’équation <i>f</i>(<i>x</i>) = <i>y</i>. Résoudre cette équation en <i>x</i>, pour <i>y</i> quelconque, fait tout à la fois : si elle a exactement une solution dans <i>D</i> pour chaque <i>y</i> ∈ <i>F</i>, <i>f</i> est bijective et la formule obtenue est <i>f</i><sup>−1</sup>. <b>Comment :</b><ol><li>pose <i>y</i> = <i>f</i>(<i>x</i>) et isole <i>x</i> ;</li><li>note les valeurs de <i>y</i> pour lesquelles c’est impossible : elles sont hors de l’image ;</li><li>vérifie que le <i>x</i> trouvé est bien dans <i>D</i>, puis écris <i>f</i><sup>−1</sup>(<i>y</i>).</li></ol>',
   demo:{enonce:`Soit <i>f</i>(<i>x</i>) = ${F('2<i>x</i> + 1','<i>x</i> − 1')} sur <i>D</i> = ℝ privé de 1. Trouver l’image de <i>f</i> et l’expression de <i>f</i><sup>−1</sup>.`,
    etapes:[{f:'<i>y</i> = (2<i>x</i> + 1)/(<i>x</i> − 1) ⇔ <i>y</i>(<i>x</i> − 1) = 2<i>x</i> + 1.',w:'On multiplie par <i>x</i> − 1 ≠ 0.'},
     {f:'⇔ <i>yx</i> − 2<i>x</i> = <i>y</i> + 1 ⇔ <i>x</i>(<i>y</i> − 2) = <i>y</i> + 1.',w:'On regroupe les termes en <i>x</i> d’un côté et on factorise.'},
     {f:'Si <i>y</i> = 2 : 0 = 3, impossible. Donc 2 n’est pas dans l’image.',w:'On ne divise par <i>y</i> − 2 qu’après avoir traité le cas où il est nul.'},
     {f:'Si <i>y</i> ≠ 2 : <i>x</i> = (<i>y</i> + 1)/(<i>y</i> − 2), unique, et <i>x</i> ≠ 1 car (<i>y</i> + 1)/(<i>y</i> − 2) = 1 donnerait 1 = −2.',w:'Une seule solution, qui est bien dans <i>D</i> : chaque <i>y</i> ≠ 2 a exactement un antécédent.'}],
    conclusion:'<i>f</i> est une bijection de ℝ privé de 1 sur ℝ privé de 2, et <i>f</i><sup>−1</sup>(<i>y</i>) = (<i>y</i> + 1)/(<i>y</i> − 2). Vérification : <i>f</i>(0) = −1 et <i>f</i><sup>−1</sup>(−1) = 0/(−3) = 0.'},
   note:'Pour une valeur isolée, inutile d’avoir la formule : <i>f</i><sup>−1</sup>(5) est la solution de <i>f</i>(<i>x</i>) = 5.'},
  {h:'Calculer une valeur de la réciproque',p:`Soit <i>f</i>(<i>x</i>) = ${F('<i>x</i> − 3','<i>x</i> + 2')}, bijection de ℝ privé de −2 sur ℝ privé de 1. Que vaut <i>f</i><sup>−1</sup>(2)&nbsp;?`,lab:'f⁻¹(2) =',ans:-7,
   why:'On résout (x − 3)/(x + 2) = 2 : x − 3 = 2x + 4, donc x = −7. Vérification : f(−7) = (−10)/(−5) = 2.'},
  {kind:'Théorie',h:'Répertoire 1 : fonctions affines et puissances',
   p:`<p>Quelques fonctions reviennent sans cesse ; il faut connaître leur graphe comme on connaît un visage. Commençons par les plus simples.</p>
${B('def','<p><b>Fonction affine</b> : <i>x</i> ↦ <i>ax</i> + <i>b</i>, définie sur ℝ. Son graphe est une <b>droite</b> de pente <i>a</i> (quand <i>x</i> augmente de 1, <i>y</i> augmente de <i>a</i>) qui coupe l’axe vertical en <i>b</i>. Si <i>a</i> = 0, elle est <b>constante</b> ; si <i>b</i> = 0, elle est <b>linéaire</b> et passe par l’origine.</p>')}
${B('def','<p><b>Fonctions puissances</b> : <i>x</i> ↦ <i>x</i>ⁿ, <i>n</i> entier ≥ 1, définies sur ℝ. Toutes passent par (0 ; 0) et (1 ; 1). Si <i>n</i> est <b>pair</b>, le graphe est en U, symétrique par rapport à l’axe vertical, et passe par (−1 ; 1). Si <i>n</i> est <b>impair</b>, le graphe est en S, symétrique par rapport à l’origine, et passe par (−1 ; −1).</p>')}
${B('idea','<p>Plus <i>n</i> est grand, plus la courbe est écrasée sur ]−1 ; 1[ (car |<i>x</i>|ⁿ devient minuscule) et plus elle grimpe vite au-delà de 1. Fais varier <i>n</i> pour le constater.</p>')}
${B('ex','<p><i>x</i> ↦ 3<i>x</i> − 2 : droite de pente 3, passant par (0 ; −2) et (1 ; 1). <i>x</i> ↦ <i>x</i>³ : S qui passe par (−2 ; −8), (0 ; 0), (2 ; 8). Reconnaître <i>x</i>² et <i>x</i>⁴ : les deux sont en U, mais <i>x</i>⁴ passe par (2 ; 16) au lieu de (2 ; 4).</p>')}`,
   params:[{id:'n',l:'exposant n',min:1,max:6,v:2}],
   draw:v=>{ const P=graph(x=>Math.pow(x,v.n),{x:[-2.5,2.5],y:[-4,4],h:260}); P.dot(1,1,{r:4,c:'var(--ink)'}).dot(-1,Math.pow(-1,v.n),{r:4,c:'var(--ink)'}); return P.svg(); },
   info:v=>`<i>x</i> ↦ <i>x</i><sup>${v.n}</sup> : ${v.n%2?'exposant impair, graphe en S symétrique par rapport à l’origine, passe par (−1 ; −1).':'exposant pair, graphe en U symétrique par rapport à l’axe vertical, passe par (−1 ; 1).'}${v.n===1?' Pour n = 1, c’est la droite y = x.':''}`},
  {kind:'Théorie',h:'Répertoire 2 : inverse, racine carrée, valeur absolue',
   p:`<p>Trois fonctions aux graphes très reconnaissables, chacune avec une particularité de domaine ou de forme.</p>
${B('def','<p><b>Inverse</b> : <i>x</i> ↦ 1/<i>x</i>, définie sur ℝ* = ℝ privé de 0. Son graphe est une <b>hyperbole</b> à deux branches, symétrique par rapport à l’origine, qui s’approche des deux axes sans jamais les toucher. Elle passe par (1 ; 1) et (−1 ; −1).</p>')}
${B('def','<p><b>Racine carrée</b> : <i>x</i> ↦ √<i>x</i>, définie sur [0 ; +∞[, à valeurs dans [0 ; +∞[. √<i>x</i> est l’unique réel positif dont le carré vaut <i>x</i>. Son graphe est une demi-parabole couchée, qui part de l’origine à la verticale puis s’aplatit ; elle passe par (1 ; 1), (4 ; 2), (9 ; 3).</p>')}
${B('def','<p><b>Valeur absolue</b> : <i>x</i> ↦ |<i>x</i>|, définie sur ℝ, qui vaut <i>x</i> si <i>x</i> ≥ 0 et −<i>x</i> si <i>x</i> &lt; 0. Son graphe est un <b>V</b> de sommet l’origine, formé des deux demi-droites <i>y</i> = <i>x</i> (à droite) et <i>y</i> = −<i>x</i> (à gauche).</p>')}
${B('warn','<p>√(<i>x</i>²) n’est pas <i>x</i> mais |<i>x</i>| : √((−3)²) = √9 = 3. Et 1/<i>x</i> n’a aucune valeur en 0 : le graphe a un trou infini, pas un point.</p>')}`,
   params:[{id:'k',l:'fonction (0 : 1/x, 1 : √x, 2 : |x|)',min:0,max:2,v:0}],
   draw:v=>{ const P=graph(null,{x:[-4,4],y:[-3,4],h:245}); if(v.k===0) P.fn(x=>1/x,{from:-4,to:-0.05}).fn(x=>1/x,{from:0.05,to:4}); else if(v.k===1) P.fn(Math.sqrt,{from:0,to:4}); else P.fn(Math.abs); if(v.k===0) P.dot(1,1,{r:4,c:'var(--ink)'}).dot(-1,-1,{r:4,c:'var(--ink)'}); if(v.k===1) P.dot(1,1,{r:4,c:'var(--ink)'}).dot(4,2,{r:4,c:'var(--ink)'}); if(v.k===2) P.dot(0,0,{r:4,c:'var(--ink)'}).dot(2,2,{r:4,c:'var(--ink)'}).dot(-2,2,{r:4,c:'var(--ink)'}); return P.svg(); },
   info:v=>['<i>x</i> ↦ 1/<i>x</i> : domaine ℝ*, deux branches, symétrique par rapport à l’origine.','<i>x</i> ↦ √<i>x</i> : domaine [0 ; +∞[, image [0 ; +∞[, courbe qui s’aplatit.','<i>x</i> ↦ |<i>x</i>| : domaine ℝ, image [0 ; +∞[, un V symétrique par rapport à l’axe vertical.'][v.k]},
  {kind:'Théorie',h:'Répertoire 3 : partie entière, sinus et cosinus',
   p:`<p>Deux familles qui sortent du cadre des formules algébriques : une fonction en escalier, et deux fonctions qui oscillent.</p>
${B('def','<p><b>Partie entière</b> : <i>x</i> ↦ ⌊<i>x</i>⌋, le plus grand entier inférieur ou égal à <i>x</i>. Ainsi ⌊2,7⌋ = 2, ⌊5⌋ = 5 et ⌊−1,5⌋ = −2 (pas −1 : on va vers la gauche). On a toujours <b>⌊<i>x</i>⌋ ≤ <i>x</i> &lt; ⌊<i>x</i>⌋ + 1</b>. Le graphe est un <b>escalier</b> : sur chaque intervalle [<i>k</i> ; <i>k</i> + 1[, la fonction vaut <i>k</i>, avec un point plein à gauche et un point vide à droite.</p>')}
${B('def','<p><b>Sinus et cosinus</b> : définis sur ℝ, à valeurs dans <b>[−1 ; 1]</b>. Leurs graphes sont des ondes de période 2π qui se déduisent l’une de l’autre par une translation de π/2. Repères : sin 0 = 0, sin(π/2) = 1, sin π = 0 ; cos 0 = 1, cos(π/2) = 0, cos π = −1. Le sinus est symétrique par rapport à l’origine, le cosinus par rapport à l’axe vertical.</p>')}
${B('idea','<p>Pour reconnaître sin et cos : regarde la valeur en 0 (0 pour le sinus, 1 pour le cosinus). Pour la partie entière : les marches montent d’une unité tous les entiers, et l’escalier reste sous la droite <i>y</i> = <i>x</i> tout en la touchant à chaque entier.</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-3,4],y:[-3,4],h:230}); P.fn(x=>x,{c:'var(--muted)',w:1.5,dash:true}); stairs(P,-3,4); P.text(2.2,3.3,'y = ⌊x⌋'); const Q=graph(null,{x:[-7,7],y:[-1.6,1.6],h:130,lab:0}); Q.fn(Math.sin).fn(Math.cos,{c:'var(--spark)'}); Q.text(-6.8,1.35,'sin',{c:'var(--accent)'}).text(-5.5,1.35,'cos',{c:'var(--spark)'}); Q.text(Math.PI,0,'π',{a:'middle',dy:16,c:'var(--muted)'}).text(2*Math.PI,0,'2π',{a:'middle',dy:16,c:'var(--muted)'}).text(-Math.PI,0,'−π',{a:'middle',dy:16,c:'var(--muted)'}); return P.svg()+'<br>'+Q.svg(); })()},
  {h:'Parties entières',p:'Calcule ⌊−2,3⌋ + ⌊2,3⌋.',lab:'résultat :',ans:-1,
   why:'⌊2,3⌋ = 2, mais ⌊−2,3⌋ = −3 (le plus grand entier qui ne dépasse pas −2,3 est −3). Somme : −3 + 2 = −1.'},
  {kind:'Méthode',h:'Reconnaître une fonction sur son graphe',
   p:'<b>Quand :</b> on te donne une courbe, ou une description, et il faut dire de quelle fonction du répertoire il s’agit (ou l’écarter). <b>Pourquoi ça marche :</b> chaque fonction du répertoire a une carte d’identité : domaine, forme globale, symétries, points de passage. Une ou deux de ces informations suffisent presque toujours à trancher. <b>Comment :</b><ol><li>le <b>domaine</b> : la courbe existe-t-elle pour <i>x</i> &lt; 0 ? y a-t-il une valeur interdite (branche qui part à l’infini) ?</li><li>la <b>forme</b> : droite, U, S, V, escalier, onde, branches ;</li><li>les <b>symétries</b> : axe vertical ou origine ;</li><li>les <b>points de passage</b> : la valeur en 0, en 1, en −1, en 2 départage les candidats restants.</li></ol>',
   demo:{enonce:'Une courbe est définie sur ℝ, symétrique par rapport à l’origine, passe par (0 ; 0), (1 ; 1) et (2 ; 8), et reste très plate près de 0. De quelle fonction du répertoire s’agit-il&nbsp;?',
    etapes:[{f:'Domaine ℝ : on écarte 1/<i>x</i> (pas définie en 0) et √<i>x</i> (pas définie pour <i>x</i> &lt; 0).',w:'Le domaine élimine d’un coup les fonctions qui ont une restriction.'},
     {f:'Symétrique par rapport à l’origine : on écarte <i>x</i>², <i>x</i>⁴, |<i>x</i>|, cos (symétriques par rapport à l’axe vertical) et la partie entière.',w:'Il reste les puissances impaires, le sinus et les fonctions linéaires.'},
     {f:'Passe par (2 ; 8) : <i>x</i> ↦ <i>x</i> donnerait 2, sin 2 ≈ 0,91, <i>x</i>³ donne 8.',w:'Un point de passage avec une abscisse différente de 0, 1 et −1 départage les candidats.'},
     {f:'Plate près de 0 : cohérent avec <i>x</i>³, dont les valeurs 0,1³ = 0,001 sont minuscules.',w:'On vérifie que tous les indices concordent.'}],
    conclusion:'C’est <i>x</i> ↦ <i>x</i>³. Les points (0 ; 0), (1 ; 1), (−1 ; −1) ne suffisaient pas : <i>x</i> ↦ <i>x</i> et <i>x</i> ↦ <i>x</i>⁵ y passent aussi.'}},
  {h:'Quelle est cette courbe ?',p:'La courbe ci-dessous est le graphe d’une fonction du répertoire. Laquelle&nbsp;?',
   fig:(()=>{ const P=graph(x=>x*x*x,{x:[-2,2],y:[-2.5,2.5],h:230,lab:1}); P.dot(0.5,0.125,{r:4,c:'var(--ink)',l:'(0,5 ; 0,125)',dy:-6}).dot(-1,-1,{r:4,c:'var(--ink)'}).dot(1,1,{r:4,c:'var(--ink)'}); return P.svg(); })(),
   opts:['<i>x</i> ↦ <i>x</i>','<i>x</i> ↦ <i>x</i>³','<i>x</i> ↦ <i>x</i>²','<i>x</i> ↦ 1/<i>x</i>'],ans:1,
   why:'Définie partout, symétrique par rapport à l’origine, en S : une puissance impaire. Le point (0,5 ; 0,125) = (0,5 ; 0,5³) tranche entre x et x³. Ce n’est pas une droite.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`${B('keep','<ul><li>Une <b>fonction réelle</b> est une application <i>f</i> : <i>D</i> → ℝ avec <i>D</i> ⊂ ℝ. <i>f</i> est la fonction, <i>f</i>(<i>x</i>) un nombre.</li><li><b>Domaine naturel</b> : dénominateurs ≠ 0, radicandes ≥ 0 (&gt; 0 sous un dénominateur) ; on prend l’intersection des conditions.</li><li><b>Image</b> <i>f</i>(<i>D</i>) = valeurs atteintes ; <b>graphe</b> = points (<i>x</i> ; <i>f</i>(<i>x</i>)). Test des verticales : une courbe est un graphe si chaque verticale la coupe au plus une fois.</li><li><b>Horizontales</b> <i>y</i> = <i>c</i> : au plus un point ⇒ injective ; au moins un point pour chaque <i>c</i> de l’arrivée ⇒ surjective. Tout dépend des ensembles choisis ; une <b>restriction</b> peut rendre <i>f</i> injective.</li><li><b>Réciproque</b> d’une bijection : <i>y</i> = <i>f</i>(<i>x</i>) ⇔ <i>x</i> = <i>f</i><sup>−1</sup>(<i>y</i>) ; on la trouve en résolvant <i>f</i>(<i>x</i>) = <i>y</i>. Graphes symétriques par rapport à <i>y</i> = <i>x</i>. <i>f</i><sup>−1</sup> ≠ 1/<i>f</i>.</li><li><b>Répertoire</b> : affine (droite, pente <i>a</i>), <i>x</i>ⁿ (U si <i>n</i> pair, S si impair, par (1 ; 1)), 1/<i>x</i> (hyperbole, ℝ*), √<i>x</i> ([0 ; +∞[), |<i>x</i>| (V), ⌊<i>x</i>⌋ (escalier, ⌊<i>x</i>⌋ ≤ <i>x</i> &lt; ⌊<i>x</i>⌋ + 1), sin et cos (ondes dans [−1 ; 1], période 2π).</li><li>Pour <b>reconnaître</b> : domaine, forme, symétries, points de passage.</li></ul>')}`},
  {kind:'Problème',h:'Une fonction homographique',
   p:'On étudie <i>f</i>(<i>x</i>) = (3<i>x</i> − 2)/(<i>x</i> + 1). On veut déterminer son domaine, son image, puis montrer qu’elle réalise une bijection entre deux parties de ℝ et calculer sa réciproque. Toute la difficulté tient dans la résolution de l’équation <i>f</i>(<i>x</i>) = <i>y</i> d’inconnue <i>x</i>.',
   fig:(()=>{ const P=graph(null,{x:[-6,5],y:[-4,8],h:260,lab:2}); P.fn(x=>(3*x-2)/(x+1),{from:-6,to:-1.15}).fn(x=>(3*x-2)/(x+1),{from:-0.6,to:5}); P.seg(-6,3,5,3,{c:'var(--spark)',w:1.5,dash:true}).seg(-1,-4,-1,8,{c:'var(--spark)',w:1.5,dash:true}); P.text(3,3,'y = 3',{dy:-6,c:'var(--spark)'}).text(-1,7,'x = −1',{dx:6,c:'var(--spark)'}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est l’unique valeur de <i>x</i> exclue du domaine de définition&nbsp;?',lab:'x =',ans:-1,hint:'Le seul obstacle est le dénominateur.',why:'x + 1 = 0 ⇔ x = −1. Le domaine est ℝ privé de −1.'},
    {q:'b) Résous <i>f</i>(<i>x</i>) = <i>y</i> d’inconnue <i>x</i>. Quelle est l’image de <i>f</i>&nbsp;?',opts:['ℝ','ℝ privé de −1','ℝ privé de 3','[3 ; +∞['],ans:2,hint:'y(x + 1) = 3x − 2 donne x(y − 3) = −y − 2. Pour quel y cette équation n’a-t-elle pas de solution ?',why:'x(y − 3) = −(y + 2). Si y = 3, on obtient 0 = −5 : impossible. Si y ≠ 3, x = (y + 2)/(3 − y) convient (et vaut jamais −1). L’image est ℝ privé de 3.'},
    {q:'c) Que vaut <i>f</i><sup>−1</sup>(1)&nbsp;?',lab:'f⁻¹(1) =',ans:1.5,tol:1e-9,hint:'Résous (3x − 2)/(x + 1) = 1.',why:'3x − 2 = x + 1 ⇔ 2x = 3 ⇔ x = 3/2. Vérification : f(1,5) = 2,5/2,5 = 1.'},
    {q:'d) Quelle est l’expression de <i>f</i><sup>−1</sup>(<i>y</i>) sur ℝ privé de 3&nbsp;?',opts:['(<i>y</i> − 2)/(<i>y</i> + 3)','(3<i>y</i> − 2)/(<i>y</i> + 1)','(<i>y</i> + 1)/(3<i>y</i> − 2)','(<i>y</i> + 2)/(3 − <i>y</i>)'],ans:3,hint:'Reprends la résolution de la question b) et isole x.',why:'x(y − 3) = −(y + 2) donne x = −(y + 2)/(y − 3) = (y + 2)/(3 − y). Test : y = 1 donne 3/2, comme en c).'},
   ],
   sol:'Domaine : ℝ privé de −1.<br>Pour y réel, f(x) = y ⇔ y(x + 1) = 3x − 2 ⇔ x(y − 3) = −(y + 2). Si y = 3, aucune solution : 3 n’est pas atteint. Si y ≠ 3, l’unique solution est x = (y + 2)/(3 − y), qui n’est jamais égale à −1 (il faudrait y + 2 = y − 3). Donc chaque y ≠ 3 a exactement un antécédent : <b>f est une bijection de ℝ privé de −1 sur ℝ privé de 3</b>, et f⁻¹(y) = (y + 2)/(3 − y).<br>En particulier f⁻¹(1) = 3/2. Sur la figure, les droites x = −1 et y = 3 sont les deux droites que la courbe approche sans les toucher : elles traduisent la valeur interdite et la valeur jamais atteinte, et le graphe de f⁻¹ s’obtient par symétrie autour de y = x.'},
  {kind:'Problème',h:'Rendre une parabole bijective',
   p:'Soit <i>f</i>(<i>x</i>) = <i>x</i>² − 4<i>x</i> + 1, définie sur ℝ. On vérifie en développant que <i>f</i>(<i>x</i>) = (<i>x</i> − 2)² − 3. Cette fonction n’est pas injective sur ℝ ; on veut choisir une restriction qui le soit, déterminer son image, et écrire la réciproque de cette restriction.',
   fig:(()=>{ const P=graph(x=>x*x-4*x+1,{x:[-2,6],y:[-4,6],h:250,lab:2}); P.fn(x=>x*x-4*x+1,{from:2,to:6,c:'var(--spark)',w:5}); P.dot(2,-3,{r:5,l:'(2 ; −3)',dy:18}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est la plus petite valeur prise par <i>f</i> sur ℝ&nbsp;?',lab:'minimum :',ans:-3,hint:'Utilise la forme (x − 2)² − 3 : un carré est toujours ≥ 0.',why:'(x − 2)² ≥ 0, avec égalité en x = 2, donc f(x) ≥ −3 et f(2) = −3. L’image de f sur ℝ est [−3 ; +∞[.'},
    {q:'b) Quel argument prouve que <i>f</i> n’est pas injective sur ℝ&nbsp;?',opts:['f(0) = f(4) = 1 : deux réels distincts ont la même image','f n’est pas surjective sur ℝ','f(2) = −3 est négatif','Le graphe est une parabole, et une parabole n’est jamais un graphe'],ans:0,hint:'Il suffit d’un seul couple de réels distincts ayant la même image.',why:'f(0) = 1 et f(4) = 16 − 16 + 1 = 1. La droite y = 1 coupe le graphe deux fois. La surjectivité n’a rien à voir avec l’injectivité.'},
    {q:'c) On restreint <i>f</i> à [2 ; +∞[ : cette restriction <i>g</i> est une bijection de [2 ; +∞[ sur [−3 ; +∞[. Que vaut <i>g</i><sup>−1</sup>(6)&nbsp;?',lab:'g⁻¹(6) =',ans:5,hint:'Résous (x − 2)² − 3 = 6 avec x ≥ 2.',why:'(x − 2)² = 9 donne x − 2 = 3 ou x − 2 = −3, soit x = 5 ou x = −1. Seul x = 5 est dans [2 ; +∞[. Vérification : f(5) = 25 − 20 + 1 = 6.'},
    {q:'d) Quelle est l’expression de <i>g</i><sup>−1</sup>(<i>y</i>) pour <i>y</i> ≥ −3&nbsp;?',opts:['2 − √(<i>y</i> + 3)','√(<i>y</i> + 3) − 2','2 + √(<i>y</i> + 3)','√(<i>y</i> − 3) + 2'],ans:2,hint:'(x − 2)² = y + 3 avec x − 2 ≥ 0.',why:'Pour x ≥ 2, x − 2 ≥ 0, donc (x − 2)² = y + 3 ⇔ x − 2 = √(y + 3) ⇔ x = 2 + √(y + 3). Test : y = 6 donne 2 + 3 = 5.'},
   ],
   sol:'f(x) = (x − 2)² − 3 ≥ −3, avec égalité en x = 2 : l’image est [−3 ; +∞[ et f n’est pas injective (f(0) = f(4) = 1 ; de façon générale f(2 + t) = f(2 − t)).<br>Sur [2 ; +∞[, la restriction g est injective : si 2 ≤ a &lt; b, alors 0 ≤ a − 2 &lt; b − 2, donc (a − 2)² &lt; (b − 2)² et g(a) &lt; g(b). Elle prend toutes les valeurs de [−3 ; +∞[ : pour y ≥ −3, l’équation (x − 2)² = y + 3 avec x ≥ 2 a l’unique solution x = 2 + √(y + 3).<br>Donc <b>g : [2 ; +∞[ → [−3 ; +∞[ est bijective et g⁻¹(y) = 2 + √(y + 3)</b> ; par exemple g⁻¹(6) = 5. En choisissant plutôt ]−∞ ; 2], on aurait obtenu la réciproque 2 − √(y + 3) : la restriction choisie décide de la réciproque.'},
]},
/* ===================== 3. CROISSANCE, EXTREMA, PARITÉ, PÉRIODICITÉ ===================== */
{subj:'gred',sem:'ana',id:'gred-variations',h:'Croissance, extrema, parité, périodicité',p:'Monotonie définie par des inégalités, fonctions bornées et extrema, symétries des graphes, périodes, opérations sur les fonctions et leur effet sur les variations, encadrements.',steps:[
  {kind:'Théorie',h:'Fonctions croissantes et décroissantes',
   p:`<p>« La courbe monte » est une impression visuelle. Pour raisonner, il faut une définition qui ne parle que de nombres : une fonction croissante <b>respecte l’ordre</b>.</p>
${B('def','<p>Soit <i>f</i> définie sur un intervalle <i>I</i>. <i>f</i> est <b>croissante</b> sur <i>I</i> si pour tous <i>x</i>₁, <i>x</i>₂ de <i>I</i> : <b><i>x</i>₁ &lt; <i>x</i>₂ ⇒ <i>f</i>(<i>x</i>₁) ≤ <i>f</i>(<i>x</i>₂)</b>. Elle est <b>décroissante</b> si <i>x</i>₁ &lt; <i>x</i>₂ ⇒ <i>f</i>(<i>x</i>₁) ≥ <i>f</i>(<i>x</i>₂). Avec des inégalités strictes à droite, on dit <b>strictement</b> croissante ou décroissante. Une fonction croissante ou décroissante est dite <b>monotone</b>.</p>')}
${B('idea','<p>Croissante : plus <i>x</i> est grand, plus <i>f</i>(<i>x</i>) est grand (ou égal). Décroissante : l’ordre est renversé. Une fonction constante est à la fois croissante et décroissante, mais ni l’une ni l’autre strictement. Sur la figure, choisis deux abscisses et compare leurs images.</p>')}
${B('ex','<p><i>x</i> ↦ 2<i>x</i> + 1 est strictement croissante sur ℝ : si <i>x</i>₁ &lt; <i>x</i>₂, alors 2<i>x</i>₁ &lt; 2<i>x</i>₂, puis 2<i>x</i>₁ + 1 &lt; 2<i>x</i>₂ + 1. <i>x</i> ↦ −3<i>x</i> est strictement décroissante : multiplier par −3 renverse les inégalités.</p>')}
${B('warn','<p>La monotonie se dit <b>sur un intervalle</b>. <i>x</i> ↦ (<i>x</i> − 1)² est décroissante sur ]−∞ ; 1] et croissante sur [1 ; +∞[, mais n’est monotone ni sur ℝ ni sur [0 ; 2].</p>')}`,
   params:[{id:'a',l:'x₁',min:-2,max:4,step:0.25,v:0},{id:'b',l:'x₂',min:-2,max:4,step:0.25,v:0.5}],
   draw:v=>{ const f=x=>(x-1)*(x-1), P=graph(f,{x:[-2.5,4.5],y:[-1,9.5],h:280,lab:1}); [v.a,v.b].forEach((x,i)=>{ P.seg(x,0,x,f(x),{c:'var(--muted)',w:1.5,dash:true}).seg(0,f(x),x,f(x),{c:'var(--muted)',w:1.5,dash:true}).dot(x,f(x),{r:6,c:i?'var(--spark)':'var(--accent)',l:i?'x₂':'x₁'}); }); return P.svg(); },
   info:v=>{ const f=x=>(x-1)*(x-1), a=Math.min(v.a,v.b), b=Math.max(v.a,v.b); if(v.a===v.b) return 'Choisis deux abscisses différentes.'; const fa=f(a), fb=f(b); return `${fmt(a)} &lt; ${fmt(b)} et <i>f</i>(${fmt(a)}) = ${fmt(fa,3)} ${fa<fb?'&lt;':fa>fb?'&gt;':'='} <i>f</i>(${fmt(b)}) = ${fmt(fb,3)} : l’ordre est ${fa<fb?'respecté':fa>fb?'renversé':'conservé au sens large'} pour ce couple.`; }},
  {kind:'Méthode',h:'Prouver une monotonie avec la définition',
   p:'<b>Quand :</b> on demande de montrer qu’une fonction est croissante ou décroissante sur un intervalle, sans outil de dérivation. <b>Pourquoi ça marche :</b> la définition compare <i>f</i>(<i>a</i>) et <i>f</i>(<i>b</i>) pour <i>a</i> &lt; <i>b</i> ; tout revient donc au <b>signe de <i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>)</b>. Si on parvient à l’écrire comme un produit de facteurs dont on connaît le signe, c’est gagné. <b>Comment :</b><ol><li>prends <i>a</i> &lt; <i>b</i> dans l’intervalle ;</li><li>calcule <i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>), réduis au même dénominateur ou factorise, en faisant apparaître <i>b</i> − <i>a</i> &gt; 0 ;</li><li>détermine le signe de chaque facteur grâce aux hypothèses sur <i>a</i> et <i>b</i>, et conclus.</li></ol>',
   demo:{enonce:'Montrer que <i>f</i>(<i>x</i>) = 1/<i>x</i> est strictement décroissante sur ]0 ; +∞[.',
    etapes:[{f:'Soient 0 &lt; <i>a</i> &lt; <i>b</i>.',w:'On prend deux réels quelconques de l’intervalle, dans l’ordre.'},
     {f:`<i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>) = ${F('1','<i>b</i>')} − ${F('1','<i>a</i>')} = ${F('<i>a</i> − <i>b</i>','<i>ab</i>')}`,w:'Même dénominateur pour voir le signe.'},
     {f:'<i>a</i> − <i>b</i> &lt; 0 et <i>ab</i> &gt; 0, donc <i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>) &lt; 0.',w:'Le numérateur est négatif car a &lt; b, le dénominateur positif car a et b le sont.'},
     {f:'Ainsi <i>a</i> &lt; <i>b</i> ⇒ <i>f</i>(<i>a</i>) &gt; <i>f</i>(<i>b</i>).',w:'C’est la définition d’une fonction strictement décroissante.'}],
    conclusion:'1/<i>x</i> est strictement décroissante sur ]0 ; +∞[ (et aussi sur ]−∞ ; 0[, par le même calcul). Mais pas sur ℝ* : −1 &lt; 1 et <i>f</i>(−1) = −1 &lt; <i>f</i>(1) = 1.'},
   note:'Pour <i>x</i>² sur [0 ; +∞[ : <i>b</i>² − <i>a</i>² = (<i>b</i> − <i>a</i>)(<i>b</i> + <i>a</i>), produit de deux positifs. Pour (<i>x</i> − 1)² : <i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>) = (<i>b</i> − <i>a</i>)(<i>a</i> + <i>b</i> − 2), dont le signe dépend de la position de <i>a</i> et <i>b</i> par rapport à 1.'},
  {h:'Sur quel intervalle ?',p:'Pour <i>f</i>(<i>x</i>) = (<i>x</i> − 1)², on calcule <i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>) = (<i>b</i> − <i>a</i>)(<i>a</i> + <i>b</i> − 2). Sur lequel de ces intervalles <i>f</i> est-elle strictement décroissante&nbsp;?',
   opts:[']−∞ ; 1]','[1 ; +∞[','ℝ','[0 ; +∞['],ans:0,
   why:'Si a &lt; b ≤ 1, alors a + b − 2 &lt; 0 et b − a &gt; 0 : la différence est négative, f décroît. Sur [1 ; +∞[, a + b − 2 &gt; 0 : f croît. Sur ℝ ou [0 ; +∞[, les deux cas se produisent.'},
  {kind:'Théorie',h:'Fonctions bornées, maximum et minimum',
   p:`${RP('<p>Un <b>majorant</b> d’une partie <i>A</i> de ℝ est un réel <i>M</i> tel que <i>a</i> ≤ <i>M</i> pour tout <i>a</i> ∈ <i>A</i>. La <b>borne supérieure</b> est le plus petit des majorants ; elle existe dès que <i>A</i> est non vide et majorée, mais n’appartient pas forcément à <i>A</i>.</p>')}
${B('def','<p><i>f</i> est <b>majorée</b> sur <i>D</i> s’il existe <i>M</i> tel que <i>f</i>(<i>x</i>) ≤ <i>M</i> pour tout <i>x</i> ∈ <i>D</i>, <b>minorée</b> s’il existe <i>m</i> tel que <i>f</i>(<i>x</i>) ≥ <i>m</i>, <b>bornée</b> si elle est les deux, ce qui revient à |<i>f</i>(<i>x</i>)| ≤ <i>K</i> pour un certain <i>K</i>. <i>f</i> admet un <b>maximum</b> en <i>x</i>₀ si <i>f</i>(<i>x</i>) ≤ <i>f</i>(<i>x</i>₀) pour tout <i>x</i> ∈ <i>D</i> : le maximum est la valeur <i>f</i>(<i>x</i>₀), un majorant <b>atteint</b>. De même pour le <b>minimum</b>.</p>')}
${B('idea','<p>Majorée : le graphe reste sous une droite horizontale. Maximum : le graphe touche cette droite. Le maximum, s’il existe, est la borne supérieure de l’image ; mais la borne supérieure peut exister sans être atteinte, et il n’y a alors pas de maximum.</p>')}
${B('ex','<p>sin est bornée (|sin <i>x</i>| ≤ 1), de maximum 1 atteint en π/2 et de minimum −1 atteint en −π/2. <i>x</i> ↦ 1/<i>x</i> sur ]0 ; 1] est minorée par 1 avec minimum 1 (en <i>x</i> = 1), mais pas majorée. <i>x</i> ↦ <i>x</i>² sur ]0 ; 2[ est minorée par 0 et majorée par 4, mais n’a ni minimum ni maximum : 0 et 4 ne sont pas atteints.</p>')}
${B('warn','<p>Ne confonds pas « majorée » et « a un maximum ». La première est une question de bornes, la seconde exige un point où la borne est touchée.</p>')}`},
  {h:'Un maximum, mais pas de minimum',p:`Soit <i>f</i>(<i>x</i>) = ${F('1','1 + <i>x</i>²')} sur ℝ. Laquelle de ces affirmations est vraie&nbsp;?`,
   opts:['<i>f</i> n’est pas majorée','<i>f</i> a un maximum 1 atteint en 0, elle est minorée par 0 mais n’a pas de minimum','<i>f</i> a un minimum 0 atteint quand <i>x</i> est très grand','<i>f</i> a un maximum 1 et un minimum 0, tous deux atteints'],ans:1,
   why:'1 + x² ≥ 1 donc f(x) ≤ 1 = f(0) : maximum 1 en 0. f(x) &gt; 0 pour tout x, et f prend des valeurs aussi petites qu’on veut : 0 est la borne inférieure, jamais atteinte.'},
  {kind:'Théorie',h:'Extrema locaux et globaux',
   p:`<p>Une colline n’est pas forcément le sommet de la chaîne. De même, une fonction peut avoir des « bosses » qui dominent leur voisinage sans être le maximum de la fonction.</p>
${B('def','<p><i>f</i> admet un <b>maximum local</b> en <i>x</i>₀ s’il existe un intervalle ouvert <i>J</i> contenant <i>x</i>₀ tel que <i>f</i>(<i>x</i>) ≤ <i>f</i>(<i>x</i>₀) pour tout <i>x</i> ∈ <i>J</i> ∩ <i>D</i>. Le maximum défini à l’étape précédente est alors dit <b>global</b>. Même chose pour les minima. Le mot <b>extremum</b> désigne un maximum ou un minimum.</p>')}
${B('idea','<p>Local : on ne regarde qu’un petit voisinage ; <i>f</i>(<i>x</i>₀) bat ses voisins immédiats. Global : <i>f</i>(<i>x</i>₀) bat toutes les valeurs. Un extremum global est automatiquement local ; la réciproque est fausse.</p>')}
${B('ex','<p><i>f</i>(<i>x</i>) = <i>x</i>³ − 3<i>x</i> sur ℝ : en <i>x</i> = −1, <i>f</i> vaut 2 et domine ses voisins (maximum local) ; en <i>x</i> = 1, <i>f</i> vaut −2 (minimum local). Mais <i>f</i>(3) = 18 &gt; 2 et <i>f</i>(−3) = −18 &lt; −2 : aucun des deux n’est global, et <i>f</i> n’est ni majorée ni minorée. Déplace la fenêtre pour tester chaque point.</p>')}
${B('warn','<p>Aux bords d’un intervalle fermé, un extremum peut exister sans « bosse » : sur [0 ; 2], <i>x</i> ↦ <i>x</i> a pour maximum 2, atteint au bord.</p>')}`,
   params:[{id:'a',l:'x₀',min:-2.5,max:2.5,step:0.25,v:0.5}],
   draw:v=>{ const f=x=>x*x*x-3*x, P=graph(f,{x:[-3,3],y:[-5,5],h:260,lab:1}); P.rect(v.a-0.5,-5,1,10,{fill:'var(--spark)',fo:.15,c:null}); P.fn(f,{from:v.a-0.5,to:v.a+0.5,c:'var(--spark)',w:4}); P.dot(v.a,f(v.a),{r:6,l:'x₀'}); return P.svg(); },
   info:v=>{ const f=x=>x*x*x-3*x; return `<i>f</i>(${fmt(v.a)}) = ${fmt(f(v.a),3)}. ${v.a===-1?'Dans la fenêtre, aucune valeur ne dépasse 2 : maximum local. Mais pas global, car f(3) = 18.':v.a===1?'Dans la fenêtre, aucune valeur n’est sous −2 : minimum local. Mais pas global, car f(−3) = −18.':'Dans la fenêtre, f prend des valeurs plus grandes et plus petites que f(x₀) : pas d’extremum local en x₀.'}`; }},
  {h:'La valeur d’un extremum local',p:'Soit <i>g</i>(<i>x</i>) = <i>x</i>³ − 3<i>x</i> + 5. Elle admet un maximum local en <i>x</i> = −1. Quelle est la valeur de ce maximum local&nbsp;?',lab:'g(−1) =',ans:7,
   why:'g(−1) = −1 + 3 + 5 = 7. Ajouter 5 à f(x) = x³ − 3x décale le graphe vers le haut sans changer la position des extrema.'},
  {kind:'Théorie',h:'Parité et imparité',
   p:`<p>Certains graphes ont une symétrie qui permet de n’étudier que la moitié de la fonction. Deux cas se présentent.</p>
${B('def','<p>Soit <i>f</i> définie sur <i>D</i> symétrique par rapport à 0 (si <i>x</i> ∈ <i>D</i>, alors −<i>x</i> ∈ <i>D</i>). <i>f</i> est <b>paire</b> si <b><i>f</i>(−<i>x</i>) = <i>f</i>(<i>x</i>)</b> pour tout <i>x</i> ∈ <i>D</i>, <b>impaire</b> si <b><i>f</i>(−<i>x</i>) = −<i>f</i>(<i>x</i>)</b> pour tout <i>x</i> ∈ <i>D</i>.</p>')}
${B('prop','<p>Le graphe d’une fonction paire est symétrique par rapport à l’<b>axe vertical</b> ; celui d’une fonction impaire est symétrique par rapport à l’<b>origine</b>.</p>')}
${B('why','<p>Soit (<i>x</i> ; <i>y</i>) un point du graphe, c’est-à-dire <i>y</i> = <i>f</i>(<i>x</i>). Si <i>f</i> est paire, <i>f</i>(−<i>x</i>) = <i>y</i> : le point (−<i>x</i> ; <i>y</i>), symétrique du premier par rapport à l’axe vertical, est aussi sur le graphe. Si <i>f</i> est impaire, <i>f</i>(−<i>x</i>) = −<i>y</i> : c’est le point (−<i>x</i> ; −<i>y</i>), symétrique par rapport à l’origine, qui est sur le graphe. Dans les deux cas, le graphe est globalement invariant par la symétrie.</p>')}
${B('ex','<p>Paires : <i>x</i>², <i>x</i>⁴, |<i>x</i>|, cos. Impaires : <i>x</i>, <i>x</i>³, 1/<i>x</i>, sin. Les noms viennent des puissances : <i>x</i>ⁿ est paire si <i>n</i> est pair, impaire si <i>n</i> est impair.</p>')}
${B('warn','<p>La plupart des fonctions ne sont ni paires ni impaires : <i>x</i> ↦ <i>x</i> + 1 vérifie <i>f</i>(−1) = 0, alors que <i>f</i>(1) = 2 et −<i>f</i>(1) = −2. Et une fonction impaire définie en 0 vérifie forcément <i>f</i>(0) = −<i>f</i>(0), donc <i>f</i>(0) = 0.</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-3,3],y:[-3,3],h:230,lab:1}); P.fn(x=>x*x/2,{c:'var(--accent)'}).fn(x=>x*x*x/4,{c:'var(--spark)'}); P.dot(2,2,{r:5,c:'var(--accent)'}).dot(-2,2,{r:5,c:'var(--accent)'}).seg(-2,2,2,2,{c:'var(--accent)',w:1.5,dash:true}); P.dot(2,2,{r:5,c:'var(--spark)'}).dot(-2,-2,{r:5,c:'var(--spark)'}).seg(-2,-2,2,2,{c:'var(--spark)',w:1.5,dash:true}); P.text(-2.9,2.6,'paire : x²/2',{c:'var(--accent)'}).text(0.3,-2.5,'impaire : x³/4',{c:'var(--spark)'}); return P.svg(); })()},
  {kind:'Méthode',h:'Étudier la parité d’une fonction',
   p:'<b>Quand :</b> avant d’étudier une fonction, pour réduire le travail à [0 ; +∞[, ou quand on demande si <i>f</i> est paire ou impaire. <b>Pourquoi ça marche :</b> la parité est une égalité entre <i>f</i>(−<i>x</i>) et ±<i>f</i>(<i>x</i>), vraie pour <b>tous</b> les <i>x</i> : on la prouve par un calcul littéral, on la réfute par un seul contre-exemple numérique. <b>Comment :</b><ol><li>vérifie que le domaine est symétrique par rapport à 0 ; sinon, <i>f</i> n’est ni paire ni impaire ;</li><li>calcule <i>f</i>(−<i>x</i>) en remplaçant <i>x</i> par −<i>x</i> partout, puis simplifie ((−<i>x</i>)² = <i>x</i>², (−<i>x</i>)³ = −<i>x</i>³, |−<i>x</i>| = |<i>x</i>|) ;</li><li>compare avec <i>f</i>(<i>x</i>) et −<i>f</i>(<i>x</i>). En cas de doute, teste une valeur : si <i>f</i>(−1) n’est ni <i>f</i>(1) ni −<i>f</i>(1), c’est réglé.</li></ol>',
   demo:{enonce:'Étudier la parité de <i>f</i>(<i>x</i>) = <i>x</i>³ − 2<i>x</i> et de <i>g</i>(<i>x</i>) = <i>x</i>² + <i>x</i>.',
    etapes:[{f:'Les deux fonctions sont définies sur ℝ, symétrique par rapport à 0.',w:'Condition préalable remplie.'},
     {f:'<i>f</i>(−<i>x</i>) = (−<i>x</i>)³ − 2(−<i>x</i>) = −<i>x</i>³ + 2<i>x</i> = −(<i>x</i>³ − 2<i>x</i>) = −<i>f</i>(<i>x</i>).',w:'On remplace x par −x et on factorise le signe.'},
     {f:'Donc <i>f</i> est impaire.',w:'L’égalité f(−x) = −f(x) est vraie pour tout x.'},
     {f:'<i>g</i>(1) = 2 et <i>g</i>(−1) = 0. Or 0 ≠ 2 et 0 ≠ −2.',w:'Un seul contre-exemple suffit pour réfuter une égalité « pour tout x ».'}],
    conclusion:'<i>f</i> est impaire ; <i>g</i> n’est ni paire ni impaire. En général, un polynôme qui ne contient que des puissances paires est pair, que des puissances impaires est impair, et un mélange des deux n’est ni l’un ni l’autre.'}},
  {h:'Paire, impaire ou ni l’un ni l’autre ?',p:'Une seule de ces fonctions est paire. Laquelle&nbsp;?',
   opts:['<i>x</i> ↦ <i>x</i>⁴ − 3<i>x</i>²','<i>x</i> ↦ <i>x</i>³ + 1','<i>x</i> ↦ <i>x</i> + 1/<i>x</i>','<i>x</i> ↦ √<i>x</i>'],ans:0,
   why:'(−x)⁴ − 3(−x)² = x⁴ − 3x² : paire. x³ + 1 : f(−1) = 0 ≠ ±2. x + 1/x est impaire. √x a un domaine [0 ; +∞[ non symétrique : ni paire ni impaire.'},
  {kind:'Théorie',h:'Périodicité',
   p:`<p>Les phénomènes qui se répètent (marées, rotation d’une roue, battement cardiaque) se décrivent par des fonctions dont le graphe se reproduit à l’identique à intervalles réguliers.</p>
${B('def','<p><i>f</i> définie sur ℝ est <b>périodique</b> s’il existe un réel <i>T</i> &gt; 0 tel que <b><i>f</i>(<i>x</i> + <i>T</i>) = <i>f</i>(<i>x</i>)</b> pour tout <i>x</i>. Un tel <i>T</i> est une <b>période</b>. S’il existe une plus petite période, on l’appelle <b>la période</b> de <i>f</i>.</p>')}
${B('idea','<p>Translater le graphe de <i>T</i> vers la gauche ou la droite le laisse inchangé. Il suffit donc de connaître <i>f</i> sur un intervalle de longueur <i>T</i>, par exemple [0 ; <i>T</i>[, pour la connaître partout. Si <i>T</i> est une période, 2<i>T</i>, 3<i>T</i>, … le sont aussi : <i>f</i>(<i>x</i> + 2<i>T</i>) = <i>f</i>(<i>x</i> + <i>T</i>) = <i>f</i>(<i>x</i>).</p>')}
${B('ex','<p>sin et cos ont pour période 2π ; 4π et 6π sont aussi des périodes, mais pas π (sin(π/2 + π) = −1 ≠ 1). La fonction <i>x</i> ↦ sin(3<i>x</i>) a pour période 2π/3, car sin(3(<i>x</i> + 2π/3)) = sin(3<i>x</i> + 2π). La fonction <i>x</i> ↦ <i>x</i> − ⌊<i>x</i>⌋ (partie décimale, dents de scie) a pour période 1.</p>')}
${B('warn','<p>Une fonction constante est périodique de toute période <i>T</i> &gt; 0 : elle n’a pas de plus petite période. Et une fonction périodique non constante n’a jamais de limite en +∞, puisqu’elle reprend indéfiniment les mêmes valeurs.</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-7,7],y:[-1.6,1.6],h:140,lab:0}); P.fn(Math.sin); P.rect(0,-1.6,2*Math.PI,3.2,{fill:'var(--spark)',fo:.15,c:null}); P.arrow(0,1.3,2*Math.PI,1.3,{c:'var(--spark)',w:2,hs:8}); P.text(Math.PI,1.3,'T = 2π',{a:'middle',dy:-6,c:'var(--spark)'}); return P.svg(); })()},
  {kind:'Pratique',h:'La plus petite période',p:'La courbe pleine est le graphe de <i>f</i>(<i>x</i>) = <i>x</i> − ⌊<i>x</i>⌋, la courbe pointillée celui de <i>x</i> ↦ <i>f</i>(<i>x</i> + <i>T</i>). Règle <i>T</i> sur la <b>plus petite</b> valeur pour laquelle les deux graphes coïncident.',
   params:[{id:'T',l:'T',min:0.25,max:3,step:0.25,v:0.5}],
   draw:v=>{ const f=x=>x-fl(x), P=graph(null,{x:[-2,4],y:[-0.5,1.6],h:170,lab:1}); for(let k=-2;k<4;k++) P.seg(k,0,k+1,1,{c:'var(--accent)',w:3.5}); for(let k=-2;k<4;k++){ const a=k-v.T, b=k+1-v.T; P.seg(a,0,b,1,{c:'var(--spark)',w:2.5,dash:true}); } return P.svg(); },
   info:v=>{ const ok=Math.abs(v.T-Math.round(v.T))<1e-9; return `<i>T</i> = ${fmt(v.T)} : les graphes ${ok?'coïncident, T est une période.':'ne coïncident pas : T n’est pas une période.'}`; },
   ok:v=>Math.abs(v.T-1)<1e-9,why:'Les dents se répètent tous les entiers : f(x + 1) = (x + 1) − ⌊x + 1⌋ = x + 1 − ⌊x⌋ − 1 = f(x). T = 2 et T = 3 sont aussi des périodes, mais la plus petite est 1.'},
  {kind:'Théorie',h:'Opérations sur les fonctions et variations',
   p:`<p>À partir de fonctions connues, on en fabrique de nouvelles. La question utile : que deviennent les variations ?</p>
${B('def','<p>Si <i>f</i> et <i>g</i> sont définies sur <i>D</i> : (<i>f</i> + <i>g</i>)(<i>x</i>) = <i>f</i>(<i>x</i>) + <i>g</i>(<i>x</i>), (<i>fg</i>)(<i>x</i>) = <i>f</i>(<i>x</i>)<i>g</i>(<i>x</i>), (λ<i>f</i>)(<i>x</i>) = λ<i>f</i>(<i>x</i>), et (<i>f</i>/<i>g</i>)(<i>x</i>) = <i>f</i>(<i>x</i>)/<i>g</i>(<i>x</i>) là où <i>g</i>(<i>x</i>) ≠ 0. La <b>composée</b> <i>g</i> ∘ <i>f</i> est <i>x</i> ↦ <i>g</i>(<i>f</i>(<i>x</i>)), définie pour les <i>x</i> ∈ <i>D</i><sub><i>f</i></sub> tels que <i>f</i>(<i>x</i>) ∈ <i>D</i><sub><i>g</i></sub> : on applique <i>f</i> d’abord, puis <i>g</i>.</p>')}
${B('prop','<ul><li>La <b>somme</b> de deux fonctions croissantes est croissante (de même pour décroissantes). Multiplier par λ &gt; 0 conserve le sens, par λ &lt; 0 le renverse.</li><li>La <b>composée</b> de deux fonctions monotones est monotone : de <b>même sens</b> ⇒ croissante, de <b>sens contraires</b> ⇒ décroissante.</li><li>Le <b>produit</b> ne suit aucune règle générale.</li></ul>')}
${B('why','<p>Somme : si <i>a</i> &lt; <i>b</i>, alors <i>f</i>(<i>a</i>) ≤ <i>f</i>(<i>b</i>) et <i>g</i>(<i>a</i>) ≤ <i>g</i>(<i>b</i>) ; on additionne les deux inégalités. Composée, cas <i>f</i> décroissante et <i>g</i> croissante : <i>a</i> &lt; <i>b</i> ⇒ <i>f</i>(<i>a</i>) ≥ <i>f</i>(<i>b</i>) ⇒ <i>g</i>(<i>f</i>(<i>a</i>)) ≥ <i>g</i>(<i>f</i>(<i>b</i>)) : chaque fonction renverse ou garde l’ordre, et on compte les renversements. Produit : <i>x</i> et <i>x</i> sont croissantes sur ℝ, mais <i>x</i> · <i>x</i> = <i>x</i>² ne l’est pas.</p>')}
${B('ex','<p><i>x</i> ↦ <i>x</i>³ + <i>x</i> est croissante sur ℝ : somme de deux croissantes. <i>x</i> ↦ √(<i>x</i> + 2) est croissante sur [−2 ; +∞[ : composée de deux croissantes. <i>x</i> ↦ 1/(<i>x</i>² + 1) sur [0 ; +∞[ : <i>x</i>² + 1 croît, 1/<i>t</i> décroît, la composée décroît.</p>')}
${B('warn','<p><i>g</i> ∘ <i>f</i> et <i>f</i> ∘ <i>g</i> sont en général différentes : avec <i>f</i>(<i>x</i>) = <i>x</i> + 1 et <i>g</i>(<i>x</i>) = <i>x</i>², <i>g</i>(<i>f</i>(<i>x</i>)) = (<i>x</i> + 1)² mais <i>f</i>(<i>g</i>(<i>x</i>)) = <i>x</i>² + 1.</p>')}`},
  {kind:'Méthode',h:'Déterminer les variations d’une composée',
   p:'<b>Quand :</b> la fonction s’écrit en emboîtant des fonctions du répertoire : racine d’une expression, inverse d’une expression, carré d’une expression… <b>Pourquoi ça marche :</b> la composée de deux monotones est monotone, et son sens se déduit en comptant les fonctions décroissantes : un nombre pair de renversements donne une croissante, un nombre impair une décroissante. <b>Comment :</b><ol><li>décompose <i>h</i> = <i>g</i> ∘ <i>u</i> : la fonction intérieure <i>u</i> et la fonction extérieure <i>g</i> ;</li><li>détermine le sens de <i>u</i> sur l’intervalle étudié, et l’intervalle de ses valeurs ;</li><li>détermine le sens de <i>g</i> <b>sur cet intervalle de valeurs</b> (1/<i>t</i> décroît seulement sur ]0 ; +∞[ ou sur ]−∞ ; 0[) ;</li><li>combine : même sens ⇒ croissante, sens contraires ⇒ décroissante.</li></ol>',
   demo:{enonce:`Déterminer les variations de <i>h</i>(<i>x</i>) = ${F('1','<i>x</i>² + 1')} sur [0 ; +∞[, puis sur ]−∞ ; 0].`,
    etapes:[{f:'<i>h</i> = <i>g</i> ∘ <i>u</i> avec <i>u</i>(<i>x</i>) = <i>x</i>² + 1 et <i>g</i>(<i>t</i>) = 1/<i>t</i>.',w:'On repère la dernière opération effectuée : ici l’inverse.'},
     {f:'Sur [0 ; +∞[, <i>u</i> est croissante et prend ses valeurs dans [1 ; +∞[.',w:'x² croît sur [0 ; +∞[, et ajouter 1 ne change pas le sens.'},
     {f:'Sur [1 ; +∞[ ⊂ ]0 ; +∞[, <i>g</i> est décroissante.',w:'L’inverse est décroissant sur les réels strictement positifs.'},
     {f:'Croissante puis décroissante : <i>h</i> est décroissante sur [0 ; +∞[.',w:'Un seul renversement de l’ordre.'},
     {f:'Sur ]−∞ ; 0], <i>u</i> est décroissante à valeurs dans [1 ; +∞[, et <i>g</i> décroissante : <i>h</i> est croissante.',w:'Deux renversements se compensent. On pouvait aussi invoquer la parité de h.'}],
    conclusion:'<i>h</i> croît sur ]−∞ ; 0], décroît sur [0 ; +∞[, et atteint son maximum 1 en 0 : c’est une « cloche ».'}},
  {h:'Une racine qui décroît',p:'Quelles sont les variations de <i>k</i>(<i>x</i>) = √(5 − <i>x</i>) sur son domaine ]−∞ ; 5]&nbsp;?',
   opts:['croissante, car la racine carrée est croissante','décroissante : 5 − <i>x</i> décroît et la racine carrée croît','croissante sur [0 ; 5] et décroissante sur ]−∞ ; 0]','ni croissante ni décroissante'],ans:1,
   why:'k = g ∘ u avec u(x) = 5 − x décroissante (valeurs dans [0 ; +∞[) et g = √ croissante sur [0 ; +∞[. Sens contraires : k est décroissante. Par exemple k(1) = 2 &gt; k(5) = 0.'},
  {kind:'Méthode',h:'Encadrer une fonction sur un intervalle',
   p:'<b>Quand :</b> on veut une borne pour <i>f</i>(<i>x</i>) quand <i>x</i> parcourt un intervalle [<i>a</i> ; <i>b</i>] : majorer une erreur, prouver qu’une fonction est bornée, préparer un argument de gendarmes. <b>Pourquoi ça marche :</b> une fonction <b>croissante</b> transporte un encadrement <i>a</i> ≤ <i>x</i> ≤ <i>b</i> en <i>f</i>(<i>a</i>) ≤ <i>f</i>(<i>x</i>) ≤ <i>f</i>(<i>b</i>) ; une fonction <b>décroissante</b> le renverse en <i>f</i>(<i>b</i>) ≤ <i>f</i>(<i>x</i>) ≤ <i>f</i>(<i>a</i>). On applique cela couche par couche, en suivant la construction de <i>f</i>. <b>Comment :</b><ol><li>pars de <i>a</i> ≤ <i>x</i> ≤ <i>b</i> ;</li><li>applique les opérations une à une (ajouter, multiplier, racine, inverse…), en renversant le sens pour chaque opération décroissante sur l’intervalle courant ;</li><li>si la fonction n’est pas monotone sur [<i>a</i> ; <i>b</i>] (un carré sur un intervalle contenant 0), découpe l’intervalle ou raisonne sur le maximum et le minimum.</li></ol>',
   demo:{enonce:`Encadrer <i>h</i>(<i>x</i>) = 2 + ${F('1','√<i>x</i>')} pour <i>x</i> ∈ [1 ; 4].`,
    etapes:[{f:'1 ≤ <i>x</i> ≤ 4 ⇒ 1 ≤ √<i>x</i> ≤ 2.',w:'La racine carrée est croissante sur [0 ; +∞[ : l’ordre est conservé.'},
     {f:`⇒ ${F('1','2')} ≤ ${F('1','√<i>x</i>')} ≤ 1.`,w:'L’inverse est décroissant sur ]0 ; +∞[ : on renverse les bornes.'},
     {f:`⇒ ${F('5','2')} ≤ 2 + ${F('1','√<i>x</i>')} ≤ 3.`,w:'Ajouter 2 conserve le sens.'}],
    conclusion:'Pour <i>x</i> ∈ [1 ; 4], 2,5 ≤ <i>h</i>(<i>x</i>) ≤ 3. Les deux bornes sont atteintes (en 4 et en 1), donc ce sont le minimum et le maximum de <i>h</i> sur [1 ; 4].'},
   note:'Piège du carré : pour <i>x</i> ∈ [−2 ; 1], on n’a pas 4 ≤ <i>x</i>² ≤ 1 (absurde). <i>x</i>² décroît sur [−2 ; 0] puis croît sur [0 ; 1] : le minimum est 0 et le maximum max(4 ; 1) = 4, donc 0 ≤ <i>x</i>² ≤ 4.'},
  {h:'Le plus petit majorant',p:'Pour <i>x</i> ∈ [−2 ; 1], quel est le plus petit majorant de <i>x</i>² − 3, autrement dit son maximum sur cet intervalle&nbsp;?',lab:'maximum :',ans:1,
   why:'Sur [−2 ; 1], 0 ≤ x² ≤ 4 (le maximum 4 est atteint en x = −2, pas en 1). Donc −3 ≤ x² − 3 ≤ 1, et le maximum est 1, atteint en x = −2.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`${B('keep','<ul><li><b>Croissante</b> sur <i>I</i> : <i>x</i>₁ &lt; <i>x</i>₂ ⇒ <i>f</i>(<i>x</i>₁) ≤ <i>f</i>(<i>x</i>₂) ; <b>décroissante</b> : l’ordre est renversé ; <b>strictement</b> avec des inégalités strictes. Preuve : signe de <i>f</i>(<i>b</i>) − <i>f</i>(<i>a</i>) pour <i>a</i> &lt; <i>b</i>, factorisé.</li><li><b>Majorée / minorée / bornée</b> ; <b>maximum</b> = majorant atteint. Une borne supérieure peut exister sans maximum.</li><li><b>Extremum local</b> : domine un voisinage ; <b>global</b> : domine tout le domaine. Global ⇒ local, pas l’inverse.</li><li><b>Paire</b> : <i>f</i>(−<i>x</i>) = <i>f</i>(<i>x</i>), graphe symétrique par rapport à l’axe vertical ; <b>impaire</b> : <i>f</i>(−<i>x</i>) = −<i>f</i>(<i>x</i>), symétrie par rapport à l’origine, et <i>f</i>(0) = 0. Domaine symétrique obligatoire ; un contre-exemple suffit à réfuter.</li><li><b>Périodique</b> : <i>f</i>(<i>x</i> + <i>T</i>) = <i>f</i>(<i>x</i>) ; sin, cos : 2π ; sin(<i>kx</i>) : 2π/<i>k</i> ; <i>x</i> − ⌊<i>x</i>⌋ : 1.</li><li><b>Opérations</b> : somme de croissantes croissante ; composée de même sens croissante, de sens contraires décroissante ; produit sans règle. <i>g</i> ∘ <i>f</i> ≠ <i>f</i> ∘ <i>g</i>.</li><li><b>Encadrer</b> : transporter <i>a</i> ≤ <i>x</i> ≤ <i>b</i> couche par couche, en renversant à chaque opération décroissante ; attention au carré sur un intervalle contenant 0.</li></ul>')}`},
  {kind:'Problème',h:'Une cloche asymétrique',
   p:'On étudie <i>f</i>(<i>x</i>) = <i>x</i>/(<i>x</i>² + 1), définie sur ℝ. On veut, sans aucun outil de dérivation, déterminer ses symétries, montrer qu’elle est bornée, et trouver son maximum et son minimum. L’ingrédient clé est l’inégalité (<i>x</i> − 1)² ≥ 0, vraie pour tout réel <i>x</i>.',
   fig:(()=>{ const P=graph(x=>x/(x*x+1),{x:[-5,5],y:[-0.8,0.8],h:160,lab:0}); P.seg(-5,0.5,5,0.5,{c:'var(--spark)',w:1.5,dash:true}).seg(-5,-0.5,5,-0.5,{c:'var(--spark)',w:1.5,dash:true}); P.dot(1,0.5,{r:5,l:'(1 ; 0,5)'}).dot(-1,-0.5,{r:5,l:'(−1 ; −0,5)',dy:18,dx:-60}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est la parité de <i>f</i>&nbsp;?',opts:['paire','impaire','ni paire ni impaire','on ne peut pas le savoir sans le graphe'],ans:1,hint:'Calcule f(−x) en remplaçant x par −x au numérateur et au dénominateur.',why:'f(−x) = (−x)/((−x)² + 1) = −x/(x² + 1) = −f(x) : f est impaire, son graphe est symétrique par rapport à l’origine.'},
    {q:'b) Développe (<i>x</i> − 1)² ≥ 0 pour obtenir une inégalité entre 2<i>x</i> et <i>x</i>² + 1. Quel est le maximum de <i>f</i> sur ℝ&nbsp;?',lab:'maximum :',ans:0.5,tol:1e-9,hint:'(x − 1)² ≥ 0 ⇔ x² + 1 ≥ 2x. Divise par x² + 1 &gt; 0.',why:'x² + 1 ≥ 2x donne f(x) = x/(x² + 1) ≤ 1/2 pour tout x, avec égalité quand (x − 1)² = 0, c’est-à-dire x = 1. Le maximum est 1/2, atteint en 1.'},
    {q:'c) Quel est le minimum de <i>f</i> sur ℝ&nbsp;?',lab:'minimum :',ans:-0.5,tol:1e-9,hint:'Utilise l’imparité : f(−x) = −f(x).',why:'Pour tout x, f(x) = −f(−x) ≥ −1/2, avec égalité pour −x = 1, soit x = −1. Minimum −1/2 atteint en −1.'},
    {q:'d) Laquelle de ces conclusions est correcte&nbsp;?',opts:['f est bornée, sans maximum ni minimum','f est majorée mais pas minorée','f est bornée : |f(x)| ≤ 1/2 pour tout x, et ces bornes sont atteintes','f n’est pas bornée car x² + 1 peut être très grand'],ans:2,hint:'Rassemble b) et c).',why:'−1/2 ≤ f(x) ≤ 1/2 pour tout x, avec égalité en −1 et en 1 : f est bornée, de maximum 1/2 et de minimum −1/2.'},
   ],
   sol:'f(−x) = −x/(x² + 1) = −f(x) : f est <b>impaire</b>.<br>Pour tout réel x, (x − 1)² ≥ 0 donne x² + 1 ≥ 2x, et comme x² + 1 &gt; 0, on peut diviser : f(x) ≤ 1/2, avec égalité si et seulement si x = 1. Donc <b>max f = 1/2</b>, atteint en 1.<br>Par imparité, f(x) = −f(−x) ≥ −1/2 avec égalité en x = −1 : <b>min f = −1/2</b>.<br>Ainsi |f(x)| ≤ 1/2 : f est bornée et ses bornes sont atteintes. Pour x grand, f(x) ≈ 1/x devient petit : la cloche redescend vers 0 de chaque côté sans jamais atteindre 0 ailleurs qu’en x = 0.'},
  {kind:'Problème',h:'La racine d’un trinôme',
   p:'Soit <i>g</i>(<i>x</i>) = √(<i>x</i>² − 2<i>x</i> + 5). On remarque que <i>x</i>² − 2<i>x</i> + 5 = (<i>x</i> − 1)² + 4. On veut déterminer le domaine de <i>g</i>, son minimum, ses variations sur [1 ; +∞[ par composition, puis exploiter une symétrie du graphe par rapport à la droite <i>x</i> = 1.',
   parts:[
    {q:'a) Quel est le domaine de définition de <i>g</i>&nbsp;?',opts:['[1 ; +∞[','ℝ privé de 1','ℝ, car (<i>x</i> − 1)² + 4 ≥ 4 &gt; 0 pour tout <i>x</i>','[−1 ; 5]'],ans:2,hint:'Le radicande est (x − 1)² + 4. Peut-il être négatif ?',why:'(x − 1)² ≥ 0 donc le radicande vaut au moins 4 : il est strictement positif pour tout x, et g est définie sur ℝ.'},
    {q:'b) Quel est le minimum de <i>g</i> sur ℝ&nbsp;?',lab:'minimum :',ans:2,hint:'Le radicande est minimal quand (x − 1)² = 0, et la racine carrée est croissante.',why:'(x − 1)² + 4 ≥ 4 avec égalité en x = 1 ; la racine carrée étant croissante, g(x) ≥ √4 = 2 = g(1). Minimum 2 atteint en 1.'},
    {q:'c) Quelles sont les variations de <i>g</i> sur [1 ; +∞[&nbsp;?',opts:['décroissante : la racine carrée inverse le sens','croissante : <i>u</i>(<i>x</i>) = (<i>x</i> − 1)² + 4 croît sur [1 ; +∞[ et la racine carrée croît','constante','croissante sur [1 ; 3] puis décroissante'],ans:1,hint:'Décompose g = √ ∘ u et détermine le sens de u sur [1 ; +∞[.',why:'Sur [1 ; +∞[, x − 1 ≥ 0 donc (x − 1)² croît, et u aussi. La racine carrée est croissante : composée de deux croissantes, g est croissante sur [1 ; +∞[. De même, g décroît sur ]−∞ ; 1].'},
    {q:'d) Montre que <i>g</i>(1 + <i>t</i>) = <i>g</i>(1 − <i>t</i>) pour tout <i>t</i>. Que vaut alors <i>g</i>(−2)², sachant que −2 = 1 − 3&nbsp;?',lab:'g(−2)² =',ans:13,hint:'g(1 + t)² = t² + 4. Calcule-le pour t = 3, ou calcule directement le radicande en x = −2.',why:'g(1 ± t) = √(t² + 4) : le graphe est symétrique par rapport à la droite x = 1. g(−2)² = g(4)² = 3² + 4 = 13 (directement : 4 + 4 + 5 = 13).'},
   ],
   sol:'Le radicande (x − 1)² + 4 est toujours ≥ 4 &gt; 0, donc g est définie sur ℝ et g(x) ≥ 2, avec égalité en x = 1 : <b>minimum 2</b>.<br>g = √ ∘ u avec u(x) = (x − 1)² + 4. Sur [1 ; +∞[, u est croissante et √ aussi : g est <b>croissante sur [1 ; +∞[</b> ; sur ]−∞ ; 1], u décroît et g décroît.<br>g(1 + t) = √(t² + 4) = g(1 − t) : la courbe est symétrique par rapport à la droite verticale x = 1, comme celle de u. En particulier g(−2) = g(4) = √13, donc g(−2)² = 13.<br>Pour x grand, g(x) ≈ |x − 1| : la courbe ressemble de loin à un V de sommet (1 ; 0), mais arrondi et relevé jusqu’à (1 ; 2).'},
]},
/* ===================== 4. CONTINUITÉ : DÉFINITION ET CONSTRUCTIONS ===================== */
{subj:'gred',sem:'ana',id:'gred-continuite',h:'Continuité : définition et constructions',p:'De l’image du crayon à la définition ε–δ, continuité en un point et sur un intervalle, exemples et contre-exemples, raccord de morceaux, puis les constructions qui préservent la continuité.',steps:[
  {kind:'Théorie',h:'Continue : une image, pas encore une définition',
   p:`<p>On dit souvent qu’une fonction est continue si on peut tracer son graphe <b>sans lever le crayon</b>. L’image est bonne : la droite <i>y</i> = <i>x</i> se trace d’un trait, alors que l’escalier de la partie entière oblige à sauter à chaque entier.</p>
${B('idea','<p>Ce que l’image veut dire : si on change <b>un peu</b> la valeur de <i>x</i>, la valeur de <i>f</i>(<i>x</i>) change aussi <b>un peu</b>. Pas de saut brusque. Pour la partie entière en 2, un déplacement minuscule de 2 vers 1,999 fait tomber la valeur de 2 à 1 : un saut de hauteur 1 pour un déplacement de 0,001.</p>')}
${B('warn','<p>Mais « sans lever le crayon » n’est pas une définition mathématique. Un crayon ne peut pas tracer une infinité de points, on ne sait pas dessiner certaines fonctions (celle qui vaut 1 sur les rationnels et 0 ailleurs), et deux personnes pourraient ne pas être d’accord sur un dessin. Pour démontrer quelque chose, il faut traduire « un peu » en inégalités, avec des nombres.</p>')}
${B('def','<p>Le programme de ce chapitre : donner un sens exact à « <i>f</i>(<i>x</i>) reste proche de <i>f</i>(<i>a</i>) quand <i>x</i> est proche de <i>a</i> », avec deux réels ε (la tolérance sur les images) et δ (la tolérance sur les abscisses). Puis vérifier que les fonctions du répertoire sont continues, repérer celles qui ne le sont pas, et montrer que les constructions usuelles (somme, produit, quotient, composée) préservent la continuité.</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-2.5,3.5],y:[-2.5,3.5],h:230,lab:1}); P.fn(x=>x,{c:'var(--ok)',w:2.5}); stairs(P,-2,4,{c:'var(--accent)'}); P.text(-2.3,2.9,'y = ⌊x⌋ : des sauts',{c:'var(--accent)'}).text(1.6,-1.6,'y = x : d’un trait',{c:'var(--ok)'}); return P.svg(); })()},
  {kind:'Théorie',h:'La définition ε–δ',
   p:`<p>Fixons une fonction <i>f</i> et un point <i>a</i> de son domaine. On veut dire : « <i>f</i>(<i>x</i>) est aussi proche qu’on veut de <i>f</i>(<i>a</i>), pourvu que <i>x</i> soit assez proche de <i>a</i> ».</p>
${B('def','<p><i>f</i> est <b>continue en <i>a</i></b> si : pour tout ε &gt; 0, il existe δ &gt; 0 tel que, pour tout <i>x</i> du domaine, <b>|<i>x</i> − <i>a</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| &lt; ε</b>. En symboles : ∀ε &gt; 0, ∃δ &gt; 0, ∀<i>x</i> ∈ <i>D</i>, |<i>x</i> − <i>a</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| &lt; ε.</p>')}
${B('idea','<p>Sur la figure : ε fixe une <b>bande horizontale</b> autour de <i>f</i>(<i>a</i>), de hauteur 2ε. δ fixe une <b>fenêtre verticale</b> autour de <i>a</i>, de largeur 2δ. La définition demande que le morceau de courbe situé dans la fenêtre reste entièrement dans la bande. Si la bande est rétrécie (ε plus petit), on a le droit de rétrécir la fenêtre (δ plus petit) : il faut seulement qu’une fenêtre convenable existe pour chaque bande.</p>')}
${B('ex','<p>Ici <i>f</i>(<i>x</i>) = <i>x</i>² et <i>a</i> = 1, donc <i>f</i>(<i>a</i>) = 1. Dans la fenêtre ]1 − δ ; 1 + δ[, l’écart |<i>x</i>² − 1| est le plus grand au bord droit et vaut (1 + δ)² − 1 = 2δ + δ². La fenêtre convient si 2δ + δ² &lt; ε. Avec ε = 0,5, δ = 0,2 convient (0,44 &lt; 0,5), mais δ = 0,25 ne convient pas (0,5625).</p>')}
<p>Règle ε puis cherche un δ qui fait passer la courbe au vert.</p>`,
   params:[{id:'e',l:'ε',min:0.1,max:1,step:0.1,v:0.5},{id:'d',l:'δ',min:0.05,max:0.5,step:0.05,v:0.3}],
   draw:v=>{ const f=x=>x*x, a=1, ok=2*v.d+v.d*v.d<v.e-1e-9, P=graph(null,{x:[-0.3,2.2],y:[-0.3,3],h:300,lab:1}); P.rect(-0.3,1-v.e,2.5,2*v.e,{fill:'var(--ok)',fo:.15,c:null}).rect(a-v.d,-0.3,2*v.d,3.3,{fill:'var(--spark)',fo:.15,c:null}); P.fn(f,{c:'var(--muted)',w:2}); P.fn(f,{from:a-v.d,to:a+v.d,c:ok?'var(--ok)':'var(--bad)',w:5}); P.seg(-0.3,1,2.2,1,{c:'var(--ok)',w:1.5,dash:true}); P.dot(a,f(a),{r:5,c:'var(--ink)',l:'(a ; f(a))'}); P.text(2.1,1+v.e,'f(a) + ε',{a:'end',dy:-4,c:'var(--ok)',s:11}).text(2.1,1-v.e,'f(a) − ε',{a:'end',dy:12,c:'var(--ok)',s:11}).text(a,-0.3,'a − δ   a + δ',{a:'middle',dy:-4,c:'var(--spark)',s:11}); return P.svg(); },
   info:v=>{ const m=2*v.d+v.d*v.d, ok=m<v.e-1e-9; return `ε = ${fmt(v.e,1)}, δ = ${fmt(v.d,2)} : l’écart maximal dans la fenêtre vaut 2δ + δ² = ${fmt(m,4)}, ${ok?'inférieur à ε : la fenêtre convient.':'qui n’est pas inférieur à ε : la courbe sort de la bande, il faut un δ plus petit.'}`; }},
  {kind:'Théorie',h:'Lire la définition pas à pas',
   p:`<p>La définition a trois quantificateurs. L’ordre est essentiel ; lisons-la comme un jeu à deux joueurs.</p>
${B('idea','<p><b>Premier coup</b> : l’adversaire choisit une tolérance ε &gt; 0, aussi petite qu’il veut. <b>Deuxième coup</b> : tu dois répondre par un δ &gt; 0, qui peut dépendre de ε (et de <i>a</i>). <b>Vérification</b> : pour tout <i>x</i> à moins de δ de <i>a</i>, <i>f</i>(<i>x</i>) doit être à moins de ε de <i>f</i>(<i>a</i>). <i>f</i> est continue en <i>a</i> si tu as une réponse gagnante <b>quel que soit</b> le ε proposé. C’est la même structure que la définition ε–N d’une limite de suite : « pour tout ε, il existe un rang <i>N</i> ».</p>')}
${B('ex','<p><i>f</i>(<i>x</i>) = 3<i>x</i> + 1 en <i>a</i> = 2, où <i>f</i>(2) = 7. On a |<i>f</i>(<i>x</i>) − 7| = |3<i>x</i> − 6| = 3|<i>x</i> − 2|. Pour que ce soit &lt; ε, il suffit que |<i>x</i> − 2| &lt; ε/3. Réponse gagnante : <b>δ = ε/3</b>. Pour ε = 0,03, δ = 0,01 ; pour ε = 3, δ = 1. La règle marche pour tous les ε : <i>f</i> est continue en 2.</p>')}
${B('def','<p>La <b>négation</b> dit ce qu’est une discontinuité en <i>a</i> : il existe ε &gt; 0 tel que, pour tout δ &gt; 0, on trouve un <i>x</i> avec |<i>x</i> − <i>a</i>| &lt; δ et pourtant |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| ≥ ε. Autrement dit : une bande que la courbe quitte dans toute fenêtre, même minuscule.</p>')}
${B('warn','<p>Il faut un δ pour <b>chaque</b> ε, pas un seul δ magique qui marcherait pour tous. Et le δ n’a pas besoin d’être le plus grand possible : n’importe quel δ qui marche suffit, et un δ plus petit qu’un δ qui marche marche aussi.</p>')}`},
  {kind:'Méthode',h:'Prouver une continuité avec ε–δ',
   p:'<b>Quand :</b> on demande de démontrer la continuité en un point « avec la définition », en général pour une fonction simple (affine, carré, inverse, valeur absolue). <b>Pourquoi ça marche :</b> on cherche à majorer |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| par une expression de la forme <i>C</i> · |<i>x</i> − <i>a</i>| ; il suffit alors de prendre δ = ε/<i>C</i>. Quand le facteur <i>C</i> dépend de <i>x</i>, on se limite d’abord à |<i>x</i> − <i>a</i>| &lt; 1 pour le borner. <b>Comment :</b><ol><li>factorise <i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>) pour faire apparaître (<i>x</i> − <i>a</i>) ;</li><li>borne l’autre facteur par une constante <i>C</i>, en supposant si besoin |<i>x</i> − <i>a</i>| &lt; 1 ;</li><li>pose δ = min(1, ε/<i>C</i>) et vérifie l’implication.</li></ol>',
   demo:{enonce:'Démontrer que <i>f</i>(<i>x</i>) = <i>x</i>² est continue en <i>a</i> = 3.',
    etapes:[{f:'<i>f</i>(<i>x</i>) − <i>f</i>(3) = <i>x</i>² − 9 = (<i>x</i> − 3)(<i>x</i> + 3).',w:'On fait apparaître le facteur x − 3, celui qu’on contrôle avec δ.'},
     {f:'Si |<i>x</i> − 3| &lt; 1, alors 2 &lt; <i>x</i> &lt; 4, donc |<i>x</i> + 3| &lt; 7.',w:'Le second facteur dépend de x ; on le borne en restant dans une fenêtre de rayon 1.'},
     {f:'Alors |<i>x</i>² − 9| = |<i>x</i> − 3| · |<i>x</i> + 3| &lt; 7|<i>x</i> − 3|.',w:'Majoration de la forme C · |x − a| avec C = 7.'},
     {f:'Soit ε &gt; 0. Posons δ = min(1, ε/7). Si |<i>x</i> − 3| &lt; δ, alors |<i>x</i> − 3| &lt; 1 et |<i>x</i>² − 9| &lt; 7 · ε/7 = ε.',w:'Le min garantit les deux conditions à la fois : la fenêtre de rayon 1 pour la borne, et ε/7 pour la précision.'}],
    conclusion:'Pour tout ε &gt; 0, on a trouvé un δ qui convient : <i>x</i> ↦ <i>x</i>² est continue en 3. Le même raisonnement en un point <i>a</i> quelconque, avec |<i>x</i> + <i>a</i>| &lt; 2|<i>a</i>| + 1, montre qu’elle est continue partout.'},
   note:'Pour une fonction affine <i>f</i>(<i>x</i>) = <i>mx</i> + <i>p</i> avec <i>m</i> ≠ 0, |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| = |<i>m</i>| · |<i>x</i> − <i>a</i>| : δ = ε/|<i>m</i>| convient, sans fenêtre préalable. Pour |<i>x</i>| : ||<i>x</i>| − |<i>a</i>|| ≤ |<i>x</i> − <i>a</i>|, donc δ = ε.'},
  {h:'Le plus grand δ',p:'<i>f</i>(<i>x</i>) = 5<i>x</i> − 2 en <i>a</i> = 1. Pour ε = 0,2, quel est le plus grand δ tel que |<i>x</i> − 1| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(1)| &lt; 0,2&nbsp;?',lab:'δ =',ans:0.04,tol:1e-9,
   why:'|f(x) − f(1)| = |5x − 2 − 3| = 5|x − 1|. On a 5|x − 1| &lt; 0,2 ⇔ |x − 1| &lt; 0,04. Donc δ = 0,04 = ε/5.'},
  {kind:'Théorie',h:'Continuité sur un intervalle',
   p:`<p>La continuité en un point est une propriété locale. Pour parler d’une fonction « continue » tout court, on la demande en chaque point.</p>
${B('def','<p><i>f</i> est <b>continue sur un intervalle <i>I</i></b> si elle est continue en chaque point <i>a</i> de <i>I</i>. On dit que <i>f</i> est <b>continue</b> si elle est continue en tout point de son domaine. Aux bords d’un intervalle fermé [<i>a</i> ; <i>b</i>], seuls les <i>x</i> du domaine comptent : en <i>a</i>, on ne regarde que les <i>x</i> ≥ <i>a</i>.</p>')}
${B('prop','<p>Si <i>f</i> est continue en <i>a</i> et <i>f</i>(<i>a</i>) &gt; 0, alors <i>f</i>(<i>x</i>) &gt; 0 pour tout <i>x</i> d’un voisinage de <i>a</i> : une fonction continue <b>garde son signe</b> autour d’un point où elle ne s’annule pas.</p>')}
${B('why','<p>Prends ε = <i>f</i>(<i>a</i>)/2 &gt; 0. La définition fournit δ tel que |<i>x</i> − <i>a</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| &lt; <i>f</i>(<i>a</i>)/2, donc <i>f</i>(<i>x</i>) &gt; <i>f</i>(<i>a</i>) − <i>f</i>(<i>a</i>)/2 = <i>f</i>(<i>a</i>)/2 &gt; 0. C’est le premier exemple d’une information « au point <i>a</i> » qui se propage « autour de <i>a</i> » grâce à la continuité.</p>')}
${B('ex','<p>Les fonctions affines, <i>x</i> ↦ <i>x</i>², <i>x</i> ↦ |<i>x</i>| sont continues sur ℝ (méthode précédente). <i>x</i> ↦ 1/<i>x</i> est continue sur ]0 ; +∞[ et sur ]−∞ ; 0[, donc continue sur son domaine ℝ* : la « coupure » en 0 n’est pas une discontinuité, puisque 0 n’est pas dans le domaine. <i>x</i> ↦ √<i>x</i> est continue sur [0 ; +∞[, y compris en 0, où |√<i>x</i> − 0| &lt; ε dès que <i>x</i> &lt; ε².</p>')}
${B('warn','<p>« Continue sur son domaine » n’est pas « continue sur ℝ ». 1/<i>x</i> est continue, mais aucune valeur en 0 ne permettrait de la prolonger en une fonction continue sur ℝ : près de 0, elle n’est pas bornée.</p>')}`},
  {kind:'Théorie',h:'Exemples et contre-exemples',
   p:`<p>Pour comprendre une définition, il faut aussi des fonctions qui ne la vérifient pas, et voir précisément où la vérification échoue.</p>
${B('ex','<p><b>La partie entière</b> est discontinue en tout entier <i>n</i>. Prenons ε = 1/2. Quel que soit δ &gt; 0, posons <i>t</i> = min(δ, 1)/2 : le réel <i>x</i> = <i>n</i> − <i>t</i> vérifie |<i>x</i> − <i>n</i>| &lt; δ, mais ⌊<i>x</i>⌋ = <i>n</i> − 1 car <i>n</i> − 1 ≤ <i>x</i> &lt; <i>n</i>, donc |⌊<i>x</i>⌋ − ⌊<i>n</i>⌋| = 1 ≥ 1/2. La bande de hauteur 1/2 autour de <i>n</i> est quittée dans toute fenêtre : c’est exactement la négation de la définition. En revanche, en un point <i>a</i> non entier, la partie entière est constante sur un petit intervalle autour de <i>a</i>, donc continue en <i>a</i> (tout δ assez petit convient).</p>')}
${B('ex','<p><b>La fonction de Dirichlet</b> vaut 1 si <i>x</i> est rationnel et 0 sinon. Tout intervalle, aussi petit soit-il, contient des rationnels et des irrationnels. Donc dans toute fenêtre autour de <i>a</i>, <i>f</i> prend les valeurs 0 et 1 : avec ε = 1/2, aucune fenêtre ne convient. Cette fonction est discontinue <b>en tout point</b>, et impossible à dessiner : c’est elle qui montre que l’image du crayon ne suffit pas.</p>')}
${B('idea','<p>Les discontinuités usuelles sont des <b>sauts</b> : la fonction s’approche d’une valeur à gauche, d’une autre à droite (ou d’une valeur différente de <i>f</i>(<i>a</i>)). Sur la figure, la bande autour de <i>f</i>(2) = 2 ne contient aucun point de la courbe à gauche de 2.</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-0.5,4.5],y:[-0.5,4.2],h:230,lab:1}); P.rect(-0.5,1.5,5,1,{fill:'var(--ok)',fo:.15,c:null}).rect(1.6,-0.5,0.8,4.7,{fill:'var(--spark)',fo:.15,c:null}); stairs(P,0,5); P.seg(-0.5,2,4.5,2,{c:'var(--ok)',w:1.5,dash:true}); P.text(4.4,2.5,'ε = 1/2',{a:'end',dy:-4,c:'var(--ok)',s:11}).text(2,-0.5,'fenêtre autour de 2',{a:'middle',dy:-4,c:'var(--spark)',s:11}); return P.svg(); })()},
  {h:'La partie entière, point par point',p:'Laquelle de ces affirmations sur <i>x</i> ↦ ⌊<i>x</i>⌋ est vraie&nbsp;?',
   opts:['Elle est discontinue en 2,5 et continue en 3','Elle est continue en 2,5 et discontinue en 3','Elle est discontinue partout','Elle est continue partout, car chaque marche est un segment'],ans:1,
   why:'Autour de 2,5, la fonction vaut 2 sur ]2 ; 3[ : constante, donc continue en 2,5. En 3, elle saute de 2 à 3 : avec ε = 1/2, aucune fenêtre ne convient.'},
  {kind:'Théorie',h:'Fonctions définies par morceaux : la condition de raccord',
   p:`<p>Beaucoup de fonctions utiles sont données par une formule à gauche d’un point <i>a</i> et une autre à droite : un tarif qui change de taux, une vitesse qui change de régime. Chaque formule est continue sur son morceau ; la seule question est le <b>point de raccord</b>.</p>
${B('def','<p>Soit <i>f</i>(<i>x</i>) = <i>g</i>(<i>x</i>) pour <i>x</i> &lt; <i>a</i> et <i>f</i>(<i>x</i>) = <i>h</i>(<i>x</i>) pour <i>x</i> ≥ <i>a</i>, où <i>g</i> et <i>h</i> sont deux fonctions continues définies autour de <i>a</i>. Alors <i>f</i> est continue en <i>a</i> si et seulement si <b><i>g</i>(<i>a</i>) = <i>h</i>(<i>a</i>)</b> : la valeur que « viserait » la formule de gauche doit coïncider avec la valeur effective <i>f</i>(<i>a</i>) = <i>h</i>(<i>a</i>).</p>')}
${B('why','<p>Si <i>g</i>(<i>a</i>) = <i>h</i>(<i>a</i>) = <i>f</i>(<i>a</i>) : pour ε &gt; 0, la continuité de <i>g</i> donne un δ₁ qui marche pour les <i>x</i> &lt; <i>a</i>, celle de <i>h</i> un δ₂ pour les <i>x</i> ≥ <i>a</i> ; δ = min(δ₁, δ₂) convient pour tous les <i>x</i>. Si au contraire <i>g</i>(<i>a</i>) ≠ <i>h</i>(<i>a</i>) : pour <i>x</i> &lt; <i>a</i> très proche de <i>a</i>, <i>f</i>(<i>x</i>) = <i>g</i>(<i>x</i>) est proche de <i>g</i>(<i>a</i>), donc à distance presque |<i>g</i>(<i>a</i>) − <i>h</i>(<i>a</i>)| de <i>f</i>(<i>a</i>) : avec ε égal à la moitié de ce saut, aucune fenêtre ne convient.</p>')}
${B('ex','<p><i>f</i>(<i>x</i>) = <i>x</i> + 1 si <i>x</i> &lt; 1, <i>f</i>(<i>x</i>) = 3 − <i>x</i> si <i>x</i> ≥ 1. En 1 : la formule de gauche vise 2, la formule de droite donne <i>f</i>(1) = 2. Raccord réussi, <i>f</i> est continue sur ℝ (figure, à gauche). Avec <i>f</i>(<i>x</i>) = 4 − <i>x</i> à droite, on aurait un saut de 2 à 3 : discontinuité en 1 (à droite).</p>')}`,
   fig:(()=>{ const P=graph(null,{x:[-1.5,3.5],y:[-0.5,3.8],h:200,lab:1}); P.fn(x=>x+1,{from:-1.5,to:1}).fn(x=>3-x,{from:1,to:3.5}).dot(1,2,{r:5,c:'var(--accent)'}); P.text(-1.3,3.4,'raccord : continue'); const Q=graph(null,{x:[-1.5,3.5],y:[-0.5,3.8],h:200,lab:1}); Q.fn(x=>x+1,{from:-1.5,to:1}).fn(x=>4-x,{from:1,to:3.5,c:'var(--bad)'}).circ(1,2,.09,{c:'var(--accent)',w:2,fill:'var(--surface)',fo:1}).dot(1,3,{r:5,c:'var(--bad)'}); Q.text(-1.3,3.4,'saut : discontinue',{c:'var(--bad)'}); return P.svg()+'<br>'+Q.svg(); })()},
  {kind:'Méthode',h:'Raccorder deux morceaux',
   p:'<b>Quand :</b> une fonction est définie par deux formules (ou plus) avec un paramètre, et on demande la valeur du paramètre qui la rend continue. <b>Pourquoi ça marche :</b> chaque formule est continue sur son morceau (ce sont des fonctions du répertoire ou des polynômes) ; seule la condition de raccord <i>g</i>(<i>a</i>) = <i>h</i>(<i>a</i>) peut échouer, et c’est une équation en le paramètre. <b>Comment :</b><ol><li>repère le point de raccord <i>a</i> et la formule qui donne <i>f</i>(<i>a</i>) (celle dont la condition contient le signe =) ;</li><li>calcule <i>f</i>(<i>a</i>) avec elle, et la valeur en <i>a</i> de l’autre formule ;</li><li>écris leur égalité et résous.</li></ol>',
   demo:{enonce:'<i>f</i>(<i>x</i>) = <i>x</i>² + <i>m</i> si <i>x</i> ≤ 1 et <i>f</i>(<i>x</i>) = 2<i>x</i> + 3 si <i>x</i> &gt; 1. Pour quelle valeur de <i>m</i> la fonction <i>f</i> est-elle continue sur ℝ&nbsp;?',
    etapes:[{f:'Sur ]−∞ ; 1[ et sur ]1 ; +∞[, <i>f</i> est continue : polynômes.',w:'Loin du raccord, aucune question ne se pose.'},
     {f:'<i>f</i>(1) = 1² + <i>m</i> = 1 + <i>m</i>.',w:'En x = 1, c’est la première formule qui s’applique (x ≤ 1).'},
     {f:'La formule de droite vise 2 · 1 + 3 = 5 en <i>x</i> = 1.',w:'On remplace x par 1 dans l’autre formule, continue elle aussi.'},
     {f:'Raccord : 1 + <i>m</i> = 5 ⇔ <i>m</i> = 4.',w:'La condition g(a) = h(a) devient une équation du premier degré.'}],
    conclusion:'Pour <i>m</i> = 4, <i>f</i> est continue sur ℝ. Pour toute autre valeur, le graphe saute en <i>x</i> = 1 de hauteur |<i>m</i> − 4|.'}},
  {kind:'Pratique',h:'Règle le raccord',p:'<i>f</i>(<i>x</i>) = 3 − <i>x</i> si <i>x</i> &lt; 2 et <i>f</i>(<i>x</i>) = <i>kx</i> − 3 si <i>x</i> ≥ 2. Règle <i>k</i> pour que <i>f</i> soit continue en 2.',
   params:[{id:'k',l:'k',min:-1,max:4,step:0.5,v:1}],
   draw:v=>{ const P=graph(null,{x:[-1,5],y:[-4,5],h:270,lab:1}); P.fn(x=>3-x,{from:-1,to:2}).fn(x=>v.k*x-3,{from:2,to:5,c:'var(--spark)'}); P.dot(2,2*v.k-3,{r:5,c:'var(--spark)'}); if(Math.abs(v.k-2)>1e-9) P.circ(2,1,.1,{c:'var(--accent)',w:2,fill:'var(--surface)',fo:1}); return P.svg(); },
   info:v=>`La formule de gauche vise 3 − 2 = 1 ; f(2) = 2k − 3 = ${fmt(2*v.k-3)}.`,
   ok:v=>Math.abs(v.k-2)<1e-9,why:'À gauche, 3 − x vise 1 en x = 2. À droite, f(2) = 2k − 3. Continuité : 2k − 3 = 1, donc k = 2.'},
  {kind:'Théorie',h:'Somme, produit, quotient de fonctions continues',
   p:`<p>Vérifier la définition ε–δ pour chaque fonction serait interminable. Comme pour les suites, on prouve une fois pour toutes que les constructions usuelles préservent la continuité.</p>
${B('thm','<p>Si <i>f</i> et <i>g</i> sont continues en <i>a</i>, alors <b><i>f</i> + <i>g</i></b>, <b>λ<i>f</i></b> et <b><i>f</i> · <i>g</i></b> sont continues en <i>a</i>. Si de plus <i>g</i>(<i>a</i>) ≠ 0, alors <b><i>f</i>/<i>g</i></b> est continue en <i>a</i>. Même énoncé sur un intervalle, le quotient étant continu là où <i>g</i> ne s’annule pas.</p>')}
${B('why','<p>Pour la somme. Soit ε &gt; 0. Comme <i>f</i> est continue en <i>a</i>, il existe δ₁ tel que |<i>x</i> − <i>a</i>| &lt; δ₁ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| &lt; ε/2 ; de même δ₂ pour <i>g</i>. Posons δ = min(δ₁, δ₂). Si |<i>x</i> − <i>a</i>| &lt; δ, l’inégalité triangulaire donne |(<i>f</i> + <i>g</i>)(<i>x</i>) − (<i>f</i> + <i>g</i>)(<i>a</i>)| ≤ |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| + |<i>g</i>(<i>x</i>) − <i>g</i>(<i>a</i>)| &lt; ε/2 + ε/2 = ε. C’est la preuve de la somme de deux limites de suites, transposée mot pour mot. Le produit utilise <i>fg</i> − <i>f</i>(<i>a</i>)<i>g</i>(<i>a</i>) = <i>f</i>(<i>g</i> − <i>g</i>(<i>a</i>)) + <i>g</i>(<i>a</i>)(<i>f</i> − <i>f</i>(<i>a</i>)) et le fait que <i>f</i> est bornée près de <i>a</i>. Pour le quotient, <i>g</i> garde son signe près de <i>a</i> (propriété vue plus haut), donc 1/<i>g</i> y est définie et bornée.</p>')}
${B('ex','<p><i>x</i> ↦ <i>x</i>² + 3<i>x</i> est continue sur ℝ (somme de deux continues). <i>x</i> ↦ (<i>x</i> + 1)/(<i>x</i> − 2) est continue sur ℝ privé de 2 : quotient de deux continues, le dénominateur ne s’annulant qu’en 2.</p>')}
${B('warn','<p>Le quotient demande <i>g</i>(<i>a</i>) ≠ 0 au point considéré. Là où <i>g</i> s’annule, la fonction <i>f</i>/<i>g</i> n’est même pas définie : la question de sa continuité en ce point ne se pose pas, mais celle d’un éventuel prolongement, oui.</p>')}`},
  {kind:'Théorie',h:'Composée ; polynômes et fractions rationnelles',
   p:`<p>Il reste l’emboîtement de fonctions. Avec lui, on obtient d’un coup la continuité de toutes les fonctions construites par formule.</p>
${B('thm','<p>Si <i>f</i> est continue en <i>a</i> et <i>g</i> continue en <i>f</i>(<i>a</i>), alors <b><i>g</i> ∘ <i>f</i></b> est continue en <i>a</i>.</p>')}
${B('why','<p>Soit ε &gt; 0. La continuité de <i>g</i> en <i>b</i> = <i>f</i>(<i>a</i>) fournit η &gt; 0 tel que |<i>y</i> − <i>b</i>| &lt; η ⇒ |<i>g</i>(<i>y</i>) − <i>g</i>(<i>b</i>)| &lt; ε. Puis la continuité de <i>f</i> en <i>a</i>, appliquée à la tolérance η, fournit δ tel que |<i>x</i> − <i>a</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>b</i>| &lt; η. En enchaînant : |<i>x</i> − <i>a</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>b</i>| &lt; η ⇒ |<i>g</i>(<i>f</i>(<i>x</i>)) − <i>g</i>(<i>b</i>)| &lt; ε. Le ε de la composée devient le η de la fonction extérieure, puis le δ de la fonction intérieure.</p>')}
${B('prop','<p>Conséquences. Les fonctions constantes et <i>x</i> ↦ <i>x</i> sont continues (δ = ε). Par produits, <i>x</i> ↦ <i>x</i>ⁿ est continue ; par sommes et multiples, <b>tout polynôme est continu sur ℝ</b>. Par quotient, <b>toute fraction rationnelle <i>P</i>/<i>Q</i> est continue sur son domaine</b> (là où <i>Q</i> ≠ 0). Par composition avec √, |·|, sin, cos (continues, admis pour sin et cos), des fonctions comme <i>x</i> ↦ √(<i>x</i>² + 1) ou <i>x</i> ↦ |<i>x</i>³ − 2<i>x</i>| sont continues sur leur domaine.</p>')}
${B('ex','<p><i>x</i> ↦ √(<i>x</i>² + 1) : <i>u</i>(<i>x</i>) = <i>x</i>² + 1 est un polynôme, continu sur ℝ, à valeurs dans [1 ; +∞[ où la racine est continue ; la composée est continue sur ℝ. <i>x</i> ↦ (<i>x</i>³ − 1)/(<i>x</i>² − 4) est continue sur ℝ privé de −2 et 2.</p>')}`},
  {kind:'Méthode',h:'Justifier la continuité d’une fonction composée',
   p:'<b>Quand :</b> on demande « montrer que <i>f</i> est continue sur son domaine », pour une fonction écrite avec des polynômes, des racines, des valeurs absolues, des quotients. <b>Pourquoi ça marche :</b> les théorèmes de construction ramènent tout aux briques (polynômes, √, |·|, sin, cos) ; il suffit de décrire comment <i>f</i> est assemblée et de vérifier à chaque étape que l’on reste dans le domaine de la brique suivante. <b>Comment :</b><ol><li>détermine le domaine <i>D</i> ;</li><li>nomme les briques et les opérations (somme, produit, quotient, composée) dans l’ordre de construction ;</li><li>pour un quotient, signale que le dénominateur ne s’annule pas sur <i>D</i> ; pour une composée, que la fonction intérieure prend ses valeurs dans le domaine de l’extérieure ;</li><li>conclus par les théorèmes.</li></ol>',
   demo:{enonce:`Montrer que <i>f</i>(<i>x</i>) = ${F('|<i>x</i>² − 3|','<i>x</i>² + 1')} est continue sur ℝ.`,
    etapes:[{f:'Domaine : ℝ, car <i>x</i>² + 1 ≥ 1 ne s’annule jamais.',w:'Le seul obstacle possible serait un dénominateur nul.'},
     {f:'<i>x</i> ↦ <i>x</i>² − 3 est un polynôme : continue sur ℝ. La valeur absolue est continue sur ℝ.',w:'On nomme les briques.'},
     {f:'Le numérateur <i>x</i> ↦ |<i>x</i>² − 3| est la composée de ces deux fonctions : continue sur ℝ.',w:'Théorème de la composée ; l’intérieure est à valeurs dans ℝ, domaine de la valeur absolue.'},
     {f:'Le dénominateur <i>x</i> ↦ <i>x</i>² + 1 est un polynôme continu, qui ne s’annule pas sur ℝ.',w:'Hypothèse indispensable du théorème du quotient.'},
     {f:'Donc <i>f</i>, quotient de deux fonctions continues à dénominateur non nul, est continue sur ℝ.',w:'Conclusion par le théorème du quotient.'}],
    conclusion:'<i>f</i> est continue sur ℝ. Aucun ε, aucun δ : le travail a été fait une fois pour toutes dans les théorèmes de construction.'}},
  {h:'La bonne justification',p:'Laquelle de ces phrases justifie correctement que <i>x</i> ↦ √(<i>x</i>² + 1) est continue sur ℝ&nbsp;?',
   opts:['Son graphe se trace sans lever le crayon','<i>x</i>² + 1 est un polynôme, continu, à valeurs dans [1 ; +∞[, et la racine carrée est continue sur [0 ; +∞[ : la composée est continue','La racine carrée est continue, donc tout ce qui contient une racine carrée est continu','Elle est paire et croissante sur [0 ; +∞[, donc continue'],ans:1,
   why:'Il faut la continuité de l’intérieure, celle de l’extérieure sur l’ensemble des valeurs de l’intérieure, et le théorème de la composée. Le dessin n’est pas une preuve, et la monotonie n’implique pas la continuité (la partie entière est croissante).'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:`${B('keep','<ul><li>« Sans lever le crayon » est une image. La <b>définition</b> : <i>f</i> continue en <i>a</i> si ∀ε &gt; 0, ∃δ &gt; 0, ∀<i>x</i> ∈ <i>D</i>, |<i>x</i> − <i>a</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| &lt; ε. Bande de hauteur 2ε, fenêtre de largeur 2δ ; l’adversaire choisit ε, tu réponds δ.</li><li><b>Prouver</b> : majorer |<i>f</i>(<i>x</i>) − <i>f</i>(<i>a</i>)| par <i>C</i>|<i>x</i> − <i>a</i>|, en se limitant si besoin à |<i>x</i> − <i>a</i>| &lt; 1 ; δ = min(1, ε/<i>C</i>). Affine : δ = ε/|<i>m</i>| ; valeur absolue : δ = ε.</li><li><b>Continue sur un intervalle</b> : en chaque point. Une fonction continue garde son signe autour d’un point où elle ne s’annule pas.</li><li><b>Contre-exemples</b> : la partie entière saute en chaque entier (ε = 1/2) ; la fonction de Dirichlet est discontinue partout.</li><li><b>Raccord</b> de deux morceaux continus en <i>a</i> : continue ⇔ les deux formules donnent la même valeur en <i>a</i>.</li><li><b>Constructions</b> : somme (ε/2 chacune, δ = min), produit, quotient (dénominateur ≠ 0), composée (ε → η → δ) de continues sont continues. Donc polynômes continus sur ℝ, fractions rationnelles sur leur domaine, et toute formule assemblée à partir de √, |·|, sin, cos continue sur son domaine.</li></ul>')}`},
  {kind:'Problème',h:'Trois morceaux à raccorder',
   p:'Une fonction <i>f</i> est définie sur ℝ par trois formules : <i>f</i>(<i>x</i>) = <i>ax</i> + 1 si <i>x</i> &lt; 0, <i>f</i>(<i>x</i>) = <i>x</i>² + <i>b</i> si 0 ≤ <i>x</i> ≤ 2, et <i>f</i>(<i>x</i>) = 2<i>x</i> + <i>c</i> si <i>x</i> &gt; 2, où <i>a</i>, <i>b</i>, <i>c</i> sont des réels. On cherche les valeurs des paramètres qui rendent <i>f</i> continue sur ℝ, puis on revient à la définition ε–δ au point 0.',
   parts:[
    {q:'a) Quelle valeur de <i>b</i> assure la continuité en 0&nbsp;?',lab:'b =',ans:1,hint:'À gauche de 0, la formule ax + 1 vise quelle valeur en x = 0 ? Et f(0) vaut 0² + b.',why:'La formule de gauche vise a · 0 + 1 = 1 quelle que soit la valeur de a ; f(0) = b. Raccord : b = 1.'},
    {q:'b) Avec cette valeur de <i>b</i>, quelle valeur de <i>c</i> assure la continuité en 2&nbsp;?',lab:'c =',ans:1,hint:'f(2) se calcule avec la formule du milieu ; la formule de droite vise 2 · 2 + c.',why:'f(2) = 4 + b = 5. La formule de droite vise 4 + c. Raccord : 4 + c = 5, donc c = 1.'},
    {q:'c) Que peut-on dire de <i>a</i>&nbsp;?',opts:['<i>a</i> doit valoir 1','<i>a</i> doit valoir 0','<i>a</i> peut être n’importe quel réel : la condition de raccord en 0 ne fait pas intervenir <i>a</i>','<i>a</i> doit être égal à <i>c</i>'],ans:2,hint:'Reprends le calcul de la question a).',why:'La droite ax + 1 passe par (0 ; 1) pour tout a. Le raccord en 0 est assuré dès que b = 1, sans condition sur a : la pente de gauche est libre.'},
    {q:'d) On prend <i>a</i> = 3, <i>b</i> = 1, <i>c</i> = 1, et ε = 0,1. Quel est le plus grand δ tel que |<i>x</i>| &lt; δ ⇒ |<i>f</i>(<i>x</i>) − <i>f</i>(0)| &lt; 0,1&nbsp;? Donne la fraction ou un arrondi au millième.',lab:'δ =',ans:1/30,tol:6e-4,hint:'Pour x &lt; 0, |f(x) − 1| = 3|x| ; pour 0 ≤ x ≤ 2, |f(x) − 1| = x². Le δ doit convenir des deux côtés.',why:'À gauche : 3|x| &lt; 0,1 ⇔ |x| &lt; 1/30 ≈ 0,033. À droite : x² &lt; 0,1 ⇔ x &lt; √0,1 ≈ 0,316. Le côté gauche est le plus exigeant : δ = 1/30.'},
   ],
   sol:'Chaque formule est un polynôme, continu sur son morceau ; seuls les raccords en 0 et en 2 posent question.<br>En 0 : la formule de gauche vise a · 0 + 1 = 1, et f(0) = b. Il faut <b>b = 1</b>, et a est libre.<br>En 2 : f(2) = 4 + 1 = 5, la formule de droite vise 4 + c. Il faut <b>c = 1</b>.<br>Avec a = 3 : pour x &lt; 0, |f(x) − f(0)| = |3x + 1 − 1| = 3|x| ; pour 0 ≤ x ≤ 2, |f(x) − 1| = x². Pour ε = 0,1, le côté gauche impose |x| &lt; 1/30 et le côté droit x &lt; √0,1 ≈ 0,316 ; le plus grand δ qui convient des deux côtés est <b>δ = 1/30</b>. Plus la pente de gauche est forte, plus δ doit être petit : la continuité est acquise pour tout a, mais le δ dépend de a.'},
  {kind:'Problème',h:'Un trou dans le graphe',
   p:'La fonction <i>f</i>(<i>x</i>) = (<i>x</i>² − 4)/(<i>x</i> − 2) est définie sur ℝ privé de 2 ; son graphe est une droite percée d’un trou. On cherche la valeur à donner en 2 pour obtenir une fonction <i>g</i> continue sur ℝ (un <b>prolongement par continuité</b>), on vérifie avec la définition, puis on examine la variante <i>h</i>(<i>x</i>) = (<i>x</i>² − 4)/|<i>x</i> − 2|.',
   fig:(()=>{ const P=graph(null,{x:[-1.5,4.5],y:[-0.5,7],h:230,lab:1}); P.fn(x=>x+2,{from:-1.5,to:4.5}); P.circ(2,4,.12,{c:'var(--accent)',w:2.5,fill:'var(--surface)',fo:1}); P.text(2,4,'trou en (2 ; 4)',{dx:10,dy:-8}); return P.svg(); })(),
   parts:[
    {q:'a) Pour <i>x</i> ≠ 2, que vaut <i>f</i>(<i>x</i>) après simplification&nbsp;?',opts:['<i>x</i> + 2','<i>x</i> − 2','<i>x</i>² − 2','2<i>x</i>'],ans:0,hint:'Factorise x² − 4 = (x − 2)(x + 2).',why:'(x² − 4)/(x − 2) = (x − 2)(x + 2)/(x − 2) = x + 2 pour x ≠ 2. Le graphe est la droite y = x + 2 sans le point (2 ; 4).'},
    {q:'b) Quelle valeur <i>g</i>(2) rend la fonction <i>g</i> (égale à <i>f</i> ailleurs) continue en 2&nbsp;?',lab:'g(2) =',ans:4,hint:'Les deux côtés du trou visent la même valeur : celle de x + 2 en x = 2.',why:'Avec g(2) = 4, g(x) = x + 2 pour tout x : une fonction affine, continue sur ℝ. Toute autre valeur crée un point isolé hors de la droite.'},
    {q:'c) Pour ε = 0,05, quel est le plus grand δ tel que |<i>x</i> − 2| &lt; δ ⇒ |<i>g</i>(<i>x</i>) − <i>g</i>(2)| &lt; 0,05&nbsp;?',lab:'δ =',ans:0.05,tol:1e-9,hint:'Calcule |g(x) − 4| avec g(x) = x + 2.',why:'|g(x) − 4| = |x + 2 − 4| = |x − 2|. L’écart sur les images est exactement l’écart sur les abscisses : δ = ε = 0,05.'},
    {q:'d) Soit <i>h</i>(<i>x</i>) = (<i>x</i>² − 4)/|<i>x</i> − 2| sur ℝ privé de 2. Peut-on la prolonger en une fonction continue sur ℝ&nbsp;?',opts:['Oui, en posant <i>h</i>(2) = 4','Oui, en posant <i>h</i>(2) = 0, la moyenne des deux côtés','Non : pour <i>x</i> &gt; 2, <i>h</i>(<i>x</i>) = <i>x</i> + 2 vise 4, mais pour <i>x</i> &lt; 2, <i>h</i>(<i>x</i>) = −(<i>x</i> + 2) vise −4 : les deux côtés ne se raccordent pas','Non, car une valeur absolue n’est jamais continue'],ans:2,hint:'Écris |x − 2| = x − 2 si x &gt; 2 et |x − 2| = −(x − 2) si x &lt; 2, puis simplifie de chaque côté.',why:'À droite de 2, h(x) = x + 2 → 4 ; à gauche, h(x) = (x − 2)(x + 2)/(−(x − 2)) = −(x + 2) → −4. Quelle que soit la valeur choisie en 2, l’un des deux côtés reste à distance au moins 4 : saut de hauteur 8, aucun prolongement continu.'},
    {q:'e) On pose <i>h</i>(2) = 4. En quels points de ℝ la fonction obtenue est-elle discontinue&nbsp;? Donne leur nombre.',lab:'nombre :',ans:1,hint:'Sur ]−∞ ; 2[ et ]2 ; +∞[, h est affine.',why:'Sur chaque demi-droite, h est affine donc continue. Le seul point de discontinuité est 2, où la formule de gauche vise −4 ≠ h(2) = 4. Un seul point.'},
   ],
   sol:'Pour x ≠ 2, f(x) = (x − 2)(x + 2)/(x − 2) = x + 2. En posant g(2) = 4, on obtient g(x) = x + 2 sur tout ℝ, fonction affine continue : c’est le <b>prolongement par continuité</b> de f, et |g(x) − 4| = |x − 2| montre que δ = ε convient toujours.<br>Pour h, on sépare les cas : si x &gt; 2, |x − 2| = x − 2 et h(x) = x + 2 ; si x &lt; 2, |x − 2| = 2 − x et h(x) = −(x + 2). Les deux formules sont continues, mais visent 4 et −4 en x = 2 : la condition de raccord ne peut pas être satisfaite, quelle que soit la valeur donnée en 2. <b>h n’admet aucun prolongement continu</b> ; avec h(2) = 4, la fonction est continue partout sauf en 2, où elle saute de hauteur 8.<br>Moralité : un trou se rebouche quand les deux côtés visent la même valeur ; sinon, c’est un saut, et aucune valeur ne le comble.'},
]},
);
})();
